{
  "name": "@codeterm/plugin-sdk",
  "version": "1.16.1",
  "type": "module",
  "description": "Type-only SDK for authoring CodeTerm plugin logic (host API + capability contracts) in TypeScript.",
  "license": "Apache-2.0",
  "repository": {
    "type": "git",
    "url": "https://github.com/domios-dev/domios.git",
    "directory": "packages/plugin-sdk"
  },
  "keywords": [
    "codeterm",
    "plugin",
    "sdk",
    "types"
  ],
  "main": "src/index.ts",
  "types": "src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  }
}

// The `host` global injected into every plugin QuickJS VM — the raw host_api.rs
// bindings plus the vm.rs preamble convenience layer. QuickJS is not a browser:

export interface ExecConversationStep {
  stdin: string;
  awaitResponseIds: number[];
}

export interface ExecOpts {
  bin: string;
  args?: string[];
  env?: Record<string, string>;
  stdin?: string;
  conversation?: ExecConversationStep[];
  timeoutMs?: number;
  detach?: boolean;
  logFile?: string;
}

export interface ExecResult {
  truncated?: boolean;
  code?: number;
  stdout?: string;
  stderr?: string;
  pid?: number;
  error?: string;
}

export interface ExecStartResult {
  jobId?: string;
  error?: string;
}

export interface ExecPollResult {
  truncated?: boolean;
  done: boolean;
  code?: number;
  stdout?: string;
  stderr?: string;
  error?: string;
}

export interface HostExec {
  (optsJson: string): string;
  // Async exec (start + poll), so the VM lock is held only for the sub-ms calls, not the command's duration.
  start(opts: ExecOpts): ExecStartResult;
  poll(jobId: string): ExecPollResult;
  close(jobId: string): void;
  // Run `opts` off the VM; the host resumes with `then` or refuses when the
  // completion event misses its bound. Must be `return`ed from the plugin method.
  async<T>(opts: ExecOpts, then: (result: ExecPollResult) => T): T;
}

export interface FetchOpts {
  url: string;
  method?: string;
  headers?: Record<string, string>;
  body?: string;
  timeoutMs?: number;
  // Templates are filled from that credential's fields (`{accessToken}`); the values themselves never enter the VM.
  credential?: CredentialRequest;
}

// `plugin.json` -> `credentials[]` declares the file and its field paths; the
// plugin only ever names the credential and the header shape it needs.
export interface CredentialRequest {
  id: string;
  headers: Record<string, string>;
}

export interface FetchResult {
  status?: number;
  headers?: Record<string, string>;
  body?: string;
  error?: string;
}

export interface FetchStreamStart {
  jobId?: string;
  error?: string;
}

export interface FetchStreamPoll {
  chunks: string[];
  done: boolean;
  status?: number;
  error?: string;
}

export interface HostFetch {
  (optsJson: string): string;
  async: <T>(opts: FetchOpts, then: (result: FetchResult) => T) => T;
  stream(opts: FetchOpts): FetchStreamStart;
  streamPoll(jobId: string): FetchStreamPoll;
  streamClose(jobId: string): void;
}

export interface DirEntry {
  name: string;
  path: string;
  isFile: boolean;
  isDir: boolean;
  size: number;
  modifiedMs: number | null;
  createdMs: number | null;
}

// Convenience layer the VM preamble adds on top of the raw JSON bridges.
export interface HostFs {
  readFile(path: string): string | null;
  // Bounded reads — up to maxBytes from the head/tail, trimmed to a valid UTF-8 boundary. Read-only.
  readFileHead(path: string, maxBytes: number): string | null;
  readFileTail(path: string, maxBytes: number): string | null;
  writeFile(path: string, contents: string): boolean;
  writeFileAtomic(path: string, contents: string): boolean;
  lockFile(path: string): string | null;
  unlockFile(id: string): boolean;
  removeFile(path: string): boolean;
  makeDirs(path: string): boolean;
  fileExists(path: string): boolean;
  isSymlink(path: string): boolean | null;
  /** `~/.domios/...` resolves inside the running instance's data dir. Prefer host.dataDir() for plugin-owned storage. */
  expandHome(path: string): string | null;
  writeTempFile(contents: string, suffix?: string): string | null;
  readDir(path: string): DirEntry[];
  walkDir(path: string, maxDepth?: number): DirEntry[];
  /** Throws RangeError when the result, or any value SQLite reads for it, passes the host's 64 MiB bound. */
  sqliteQuery<T = Record<string, unknown>>(
    db: string,
    sql: string,
    params?: unknown[],
  ): T[];
  /** The same rows as sqliteQuery, read on a host thread; the method must return this call's result. */
  sqliteQueryAsync<T = Record<string, unknown>, R = unknown>(
    db: string,
    sql: string,
    params: unknown[] | null | undefined,
    then: (rows: T[]) => R,
  ): R;
  readJson<T = unknown>(path: string): T | null;
  writeJson(path: string, value: unknown): boolean;
}

export interface HostShell {
  quote(s: string): string;
  quoteFor(s: string, platform: string): string;
  // Cross-platform "set env var for the next command" prefix — POSIX uses
  // inline assignment (no `&&`/`;` chaining needed), Windows uses `$env:`.
  envPrefix(name: string, value: string, platform: string): string;
}

export interface HostPath {
  isWindows: boolean;
  toForwardSlash(p: string): string;
  toNative(p: string): string;
  normalize(p: string): string;
  equal(a: string, b: string): boolean;
}

// ── host compute base (host.worker / workspace / agent / mem) ──

export interface Backend {
  provider?: string;
  model?: string;
}

export interface TabRef {
  tabId: string;
  title?: string;
  // "Shell" | "Agent" | "ChatBackend" — the tab's backing discriminator (F1).
  backing?: string;
}

// Read-only mirror of the host's parseUsage output (tokens/cost); loosely typed since provider shapes vary.
export interface UsageSnapshot {
  resets?: import("./agentRuntime").ResetCredits | null;
  billing_mode: "subscription" | "api" | "unknown";
  limits_reported: boolean;
  inputTokens?: number;
  outputTokens?: number;
  totalTokens?: number;
  costUsd?: number;
  [key: string]: unknown;
}

// One-shot agent compute: start() enqueues and returns immediately, poll() reads the result. Sync per step.
export interface HostWorker {
  start(opts: { backend?: Backend; task: string }): { jobId: string };
  poll(jobId: string): { done: boolean; report?: string; error?: string };
}

// Synchronous: workspace ensure/list are cheap mux ops, not agent turns.
export interface HostWorkspace {
  ensure(opts: { name: string; externalRoot?: string }): { workspaceId: string };
  tabs(workspaceId: string): TabRef[];
}

// session), get (the plugin's key→session map). send/poll is the job-id bridge — the VM never blocks.
export interface HostAgent {
  spawn(
    workspaceId: string,
    opts: { backend?: Backend; task: string; key?: string; commands?: string[] },
  ): { sessionId: string };
  resume(workspaceId: string, sessionId: string): { sessionId: string } | null;
  get(workspaceId: string, key: string): { sessionId: string } | null;
  send(sessionId: string, text: string): { ticket: string };
  poll(ticket: string): { done: boolean; reply?: string; error?: string };
  reap(sessionId: string): void;
  usage?(sessionId: string): UsageSnapshot | null;
}

// Synchronous: mem search is sync, so a sync stage like chatPreprocess can use the hits directly mid-turn.
export interface HostMem {
  search(opts: {
    query: string;
    k?: number;
  }): { hits: { id: string; text: string; score: number }[] };
}

// ── host.analytics (machine-wide KPI aggregates; needs permissions.analytics) ──

export type AnalyticsBucket = "day" | "week";
export type AnalyticsGroupBy = "provider_model" | "workspace" | "team" | "plan";
export type AnalyticsCoverage = "recorded" | "partial" | "not_recorded";
export type AnalyticsDimension = "provider" | "model" | "workspace" | "team" | "plan";
export type AnalyticsKeyReason =
  | "provider_not_reported"
  | "model_not_reported"
  | "workspace_not_recorded"
  | "workspace_deleted"
  | "no_plan"
  | "plan_deleted"
  | "no_team"
  | "team_deleted";

export interface AnalyticsModelKey {
  provider: string;
  model: string | null;
}

// Local calendar days, inclusive, at most 92; day buckets at most 31.
export interface AnalyticsQuery {
  range: { from: string; to: string; tz: string };
  bucket: AnalyticsBucket;
  // Choices in one list widen; lists narrow each other. null selects the null key.
  filters?: {
    providers?: string[];
    models?: AnalyticsModelKey[];
    workspaces?: (string | null)[];
    teams?: (string | null)[];
    plans?: (string | null)[];
  };
  group_by: AnalyticsGroupBy;
  scope?: { kind: "machine"; includes_mesh_peers?: false };
}

export interface AnalyticsTotals {
  new_input: number;
  generated: number;
  read_from_cache: number;
  turns: number;
}

export interface AnalyticsGroupKey {
  dimension: AnalyticsDimension;
  id: string | null;
  provider?: string;
  reason?: AnalyticsKeyReason;
}

export interface AnalyticsGroup {
  key: AnalyticsGroupKey;
  label: string | null;
  totals: AnalyticsTotals;
  children?: AnalyticsGroup[];
}

export interface AnalyticsTokenBucket {
  start: number;
  end: number;
  label: string;
  coverage: AnalyticsCoverage;
  totals: AnalyticsTotals | null;
  groups: { key: AnalyticsGroupKey; totals: AnalyticsTotals }[];
}

export interface AnalyticsTabBucket {
  start: number;
  end: number;
  label: string;
  coverage: AnalyticsCoverage;
  total: number | null;
}

export interface AnalyticsAllowance {
  provider: string;
  allowance: {
    captured_at: number;
    session_used_pct: number | null;
    session_resets_at: number | null;
    weekly_used_pct: number | null;
    weekly_resets_at: number | null;
    stale_reason: string | null;
  };
  attribution: {
    model: "unavailable";
    workspace: "unavailable";
    team: "unavailable";
    plan: "unavailable";
  };
}

// Every missing figure is null, never 0.
export interface AnalyticsSnapshot {
  scope: { kind: "machine"; includes_mesh_peers: false };
  as_of: number;
  range: { from: string; to: string; tz: string };
  bucket: AnalyticsBucket;
  group_by: AnalyticsGroupBy;
  recording: {
    state: "recording" | "disabled" | "unavailable";
    reason: string | null;
    enable_setting: string | null;
    first_recorded_at: number | null;
    last_recorded_at: number | null;
    workspace_recorded_since: number | null;
  };
  tokens: {
    totals: AnalyticsTotals | null;
    series: AnalyticsTokenBucket[];
    groups: AnalyticsGroup[];
  };
  tabs_created: {
    state: "counted" | "not_counted" | "not_attributed";
    counted_since: number | null;
    total: number | null;
    by_kind: { agent: number; terminal: number } | null;
    series: AnalyticsTabBucket[];
  };
  allowance: AnalyticsAllowance[];
  money: { state: "not_recorded" };
}

export interface AnalyticsRefusal {
  error: "invalid_query" | "foreign_scope" | string;
  message?: string;
}

// null = the host could not answer at all.
export interface HostAnalytics {
  query(query: AnalyticsQuery): AnalyticsSnapshot | AnalyticsRefusal | null;
}

// The calling plugin's own receiver binding. Only host chrome (tab menu, API, CLI) assigns a tab.
export interface ReceiverTargetView {
  pluginId: string;
  // null resolves General at recording START; an explicit stale recording target refuses.
  tabId: string | null;
  // Webhooks retain their General fallback; local recording requires a live frozen recipient.
  live: boolean;
}

export interface ReceiverTargetRefusal {
  error: "receiver_not_found" | "persist_failed" | "receiver_target_unavailable" | string;
  message?: string;
}

export interface HostReceiverTarget {
  get(): ReceiverTargetView | ReceiverTargetRefusal | null;
  clear(): ReceiverTargetView | ReceiverTargetRefusal | null;
}

export interface LocalRecordingStatus {
  pluginId: string;
  granted: boolean;
  enabled: boolean;
  devicesSelected: boolean;
  available: boolean;
  captureActive: boolean;
  generation: number;
}

export interface LocalRecordingRefusal {
  error: string;
}

export interface RecordingDeviceSelection {
  inputId: string;
  collectionId: string;
  microphoneId: string;
}

export interface RecordingInputDevice {
  id: string;
  label: string;
  kind: "hid" | "audio_input";
  connected: boolean;
  inputId: string;
  collectionId: string;
}

export interface HostLocalRecording {
  listInputDevices(): RecordingInputDevice[] | LocalRecordingRefusal | null;
  selectDevices(devices: RecordingDeviceSelection): number | LocalRecordingRefusal | null;
  savedSelection(): RecordingDeviceSelection | LocalRecordingRefusal | null;
  statusReport(): number[] | LocalRecordingRefusal | null;
  status(): LocalRecordingStatus | LocalRecordingRefusal | null;
  setEnabled(enabled: boolean): LocalRecordingStatus | LocalRecordingRefusal | null;
}

// Acts on the calling agent's authorized surface; only inside onAgentCommand, with the `surfaces` grant.
export interface HostSurface {
  // Returns the JSON text `{ "result": string }` or `{ "error": string }`.
  call(verb: string, argsJson: string): string;
  /** Identity only; plugin identity comes from the sandbox. Returns {ok:true} or {error}. */
  invalidate(identity: { surface: string; instance: string; tab: string }): { ok: true } | { error: string };
}

export interface HostProgressOpts {
  label: string;
  percent?: number;
  done?: boolean;
  error?: string;
}

export interface Host {
  commandTranscriptStdout(recordJson: string, declarationJson: string): string | null;
  platform(): string;
  homeDir(): string | null;
  /** Instance data root; returning the path grants no filesystem access. */
  dataDir(): string;
  expandHome(path: string): string | null;
  envGet(name: string): string | null;
  providerVersionJson(): string;
  // Non-secret fields of a manifest-declared credential, as a JSON object.
  // Secret fields are never returned — see `FetchOpts.credential`.
  credentialPublic(id: string): string | null;
  unixNow(): number;
  unixNowMs(): number;
  md5(s: string): string;

  fileExists(path: string): boolean;
  readFile(path: string): string | null;
  readFileHead(path: string, maxBytes: number): string | null;
  readFileTail(path: string, maxBytes: number): string | null;
  writeFile(path: string, contents: string): boolean;
  writeFileAtomic(path: string, contents: string): boolean;
  canonicalPath(path: string): string | null;
  projectWriteAllowed(root: string): boolean;
  jsonBooleanRecord(path: string, keysJson: string, grant: boolean): string;
  lockFile(path: string): string | null;
  unlockFile(id: string): boolean;
  removeFile(path: string): boolean;
  makeDirs(path: string): boolean;
  isSymlink(path: string): boolean | null;
  readDirJson(path: string): string | null;
  walkDirJson(path: string, maxDepth: number): string | null;
  writeTempFile(contents: string, suffix?: string): string | null;
  sqliteQueryAllJson(db: string, sql: string, paramsJson?: string | null): string | null;
  sqliteQueryStart(db: string, sql: string, paramsJson?: string | null): string;

  shellQuote(s: string): string;
  shellQuoteFor(s: string, platform: string): string;
  shellEnvPrefix(name: string, value: string, platform: string): string;

  log(level: "trace" | "debug" | "info" | "warn" | "error", msg: string): void;

  settingsJson(): string;
  exec: HostExec;
  execStart(optsJson: string): string;
  execPoll(jobId: string): string;
  execClose(jobId: string): void;
  // The VM must yield while the job completes so a plugin cannot block other calls.
  awaitJob<T, R = ExecPollResult>(jobId: string, then: (result: R) => T): T;
  fetch: HostFetch;
  fetchStart(optsJson: string): string;
  fetchStream(optsJson: string): string;
  fetchStreamPoll(jobId: string): string;
  fetchStreamClose(jobId: string): void;
  secretGet(name: string): string | null;
  secretSet(name: string, value: string): boolean;
  secretDelete(name: string): boolean;
  // Tolerant tool-call extractor returning a tri-state JSON `status` so "no call"
  // (`none`) is never confused with "broken call" (`malformed`, must be retried) vs `ok`.
  toolcallParse(rawText: string, schemaJson: string): string;

  manifestJson(): string | null;
  manifest(): unknown;

  fs: HostFs;
  shell: HostShell;
  path: HostPath;
  // Preamble convenience: host.toolcall.parse -> host.toolcallParse.
  toolcall: { parse(rawText: string, schemaJson: string): string };
  progress(opts: HostProgressOpts): void;

  worker: HostWorker;
  workspace: HostWorkspace;
  agent: HostAgent;
  mem: HostMem;
  analyticsQuery(queryJson: string): string;
  analytics: HostAnalytics;
  receiverTargetGet(): string;
  receiverTargetClear(): string;
  receiverTarget: HostReceiverTarget;
  localRecordingStatus(): string;
  localRecordingSetEnabled(enabled: boolean): string;
  localRecording: HostLocalRecording;
  surfaceCall(verb: string, argsJson: string): string;
  surface: HostSurface;
}

declare global {
  // QuickJS injects `host` as a global before the plugin body runs.
  const host: Host;
}

import type { AgentRuntime } from "./agentRuntime";
import type { ParsedSessionRecord, SessionRecordsMeta } from "./jsonlRecords";
export type PreTrustOutcome =
  | { status: "already_trusted" | "granted" }
  | { status: "skipped" | "failed"; reason: string };

// Plugin-facing capability contracts. Each capability is one Rust trait the host
// adapts to a `plugin.js` export; shapes mirror how the host consumes them.

// ── Shared context ──

import type { ModelProviderConfig } from "./modelProviders";
import type {ProviderAuthStatus, ProviderSessionObservations} from "./providerSignals";
import type { ChatMsg } from "./gen/ChatMsg";

/** Manifest spawn.turnEvidenceNormalization; applies symmetrically to exact user-turn matching. */
export interface TurnEvidenceNormalization {
  unwrapPastedContentWrapper?: boolean;
  collapseHorizontalWhitespace?: boolean;
  dropSupplementaryCharacters?: boolean;
  dropLineBreaks?: boolean;
}

/** Manifest spawn contract; absent means the provider does not restore chat on resume. */
export interface ResumeHistoryCapability {
  restoresConversationHistoryOnResume?: boolean;
}

export interface SessionResumeCapability {
  exact: boolean;
}

export interface TabContext {
  tabId?: string;
  cwd?: string | null;
}

export interface SessionDeltaContext {
  session_key: string;
  from_offset: number;
}

export interface SessionModelTranscriptBoundary {
  lastEntryUuid: string | null;
  lastEntryTimestamp: string | null;
  lastEntryType: string | null;
  boundaryFound: boolean;
}

// ── statusBubble ──

export type BubbleTone = "default" | "muted" | "ok" | "warn" | "danger" | "accent";

export interface StatusBubble {
  label: string;
  tone: BubbleTone;
  icon?: string;
  tooltip?: string;
  // "openPanel:view:<id>" opens the plugin's iframe view; "openPanel:<name>" a built-in panel.
  action?: string;
}

// ── glanceView (mirrors src-tauri/crates/codeterm-service-core/src/view/mod.rs ViewNode) ──

export type Tone = "default" | "muted" | "ok" | "warn" | "danger" | "accent";
export type Spacing = "none" | "sm" | "md" | "lg";
export type NoteLevel = "info" | "warn" | "error";

export interface NodeStyle {
  tone?: Tone;
  spacing?: Spacing;
}

export type ViewNode =
  | { kind: "text"; text: string; style?: NodeStyle }
  | {
      kind: "stat";
      label: string;
      value: string;
      unit?: string;
      style?: NodeStyle;
    }
  | { kind: "keyVal"; key: string; value: string; style?: NodeStyle }
  | { kind: "badge"; label: string; tone?: Tone }
  | { kind: "row"; children: ViewNode[]; style?: NodeStyle }
  | { kind: "stack"; children: ViewNode[]; style?: NodeStyle }
  | { kind: "divider" }
  | { kind: "note"; body: string; level?: NoteLevel }
  | { kind: "button"; label: string; action: string; style?: NodeStyle };

export interface GlanceView {
  title?: string;
  nodes: ViewNode[];
}

// ── view (sandboxed iframe UI bridge target) ──

export type ViewCall = (method: string, args: unknown) => unknown;

// ── agentProvider ──
// Method set mirrors plugins/provider-*/plugin.js + the AgentProvider trait.

export interface ContextAttach { editable: boolean; readOnly: boolean; }
export interface ContextFiles { edit: string[]; read: string[]; }
export interface HostOwnedCapabilities { questions: boolean; todos: boolean; }

export interface LaunchParams {
  contextFiles?: ContextFiles;
  /** Absolute host-owned shared instructions file; an unreadable supplied path must refuse launch. */
  toolLessInstructionsPath?: string;
  skipPermissions?: boolean;
  hostOwned?: HostOwnedCapabilities;
  args?: string[];
  agentName?: string;
  sessionId?: string;
  task?: string;
  /** Optional provider-visible starter turn selected by the host. */
  starterPrompt?: "no_starter" | "assigned_task" | "idle_wakeup" | "team_bootstrap" | "general_bootstrap" | "startup_handshake";
  /** Host-owned text for starter prompts shared across providers. */
  starterPromptText?: string;
  /** Host-owned opening frame for the selected starter turn. */
  starterPromptPrefix?: string;
  /// Fixed local server the host wants this agent's structured-prompt handle to
  /// listen on. Set only for providers that declare `supportsStructuredPrompts`;
  /// the plugin maps it to the provider's own server flags (opencode:
  /// `--hostname <h> --port <p>`).
  structuredPromptServer?: { hostname: string; port: number };
  /** Host-minted inert token a provider may carry into its own session record. */
  launchMarker?: string;
  /** Stable identity for the CodeTerm data directory writing this launch. */
  instanceId?: string;
  [key: string]: unknown;
}

export interface LaunchArtifactSweepRequest {
  instanceId: string;
  liveTabIds: string[];
  /** Host holds each registered instance's exclusive lifetime lock throughout this call. */
  goneInstanceIds?: string[];
  confirm: boolean;
  includeLegacy: boolean;
}

export interface LaunchArtifactSweepReport {
  dead: string[];
  legacy: string[];
  removed: string[];
}

/** One process in the tab's own PTY tree; `startToken` is its OS process start time. */
export interface LaunchProcess {
  pid: number;
  depth: number;
  startToken: string;
}

/** Everything the host knows about one launch, and nothing about any other. */
export interface LaunchSessionEvidence {
  cwd: string;
  launchMarker?: string | null;
  launchedAtMs: number;
  processes: LaunchProcess[];
}

/** Provider-authoritative top-level completion, including automatic continuations. */
export type ReplyRelayEvidence = ReplyRelayTurn | {
  userTurnId: string;
  userRecordStart: number;
  userText: string;
  complete: false;
  outcome: "error" | "cancelled" | "reflection_limit";
} | {
  unavailable: true;
  reason: string;
};

export interface ReplyRelayTurn {
  userTurnId: string;
  /** UTF-8 byte start of the original user record; IDs remain stable in the own-session history. */
  userRecordStart: number;
  userText: string;
  assistantTurnId: string;
  answer: string;
  complete: true;
}

export interface LaunchSessionDetection {
  sessionId: string;
  source: "pid_registry" | "launch_marker";
}

/** Full launch context for a resumed session, not just its id. */
export interface ResumeParams {
  cwd?: string | null;
  contextFiles?: ContextFiles | null;
  toolLessInstructionsPath?: string | null;
  sessionId: string;
  skipPermissions?: boolean;
  hostOwned?: HostOwnedCapabilities;
  agentName?: string | null;
  instanceId?: string | null;
  /** Composed system prompt to re-apply; absent when the host has none. */
  systemPrompt?: string | null;
  args?: string[];
  [key: string]: unknown;
}

// picker can't read its layout (e.g. opencode's single-row options).
export interface ParsedPrompt {
  question: string;
  options: [string, string][];
  sections?: Array<{ label: string; active?: boolean; completed?: boolean }>;
  multiSelect?: boolean;
  submitAvailable?: boolean;
  selectedValues?: string[];
}

// ── tab-state classification (mirrors codeterm-plugin tab_state.rs) ──

export type TabState =
  | "working"
  | "waiting_on_auth"
  | "update_prompt"
  | "rate_limited"
  | "clarifying_question"
  | "idle_stuck"
  | "unknown";

/** Host-built snapshot of the tab's OWN session/screen handed to classifyTabState. */
export interface TabStateSnapshot {
  tabId: string;
  agentType: string;
  sessionId?: string | null;
  cwd?: string | null;
  /** Recent rendered screen tail (provider fingerprints match against this). */
  screenText: string;
}

export interface DelayedResume {
  /** ISO-8601 wall-clock time to fire the resume. */
  at: string;
  text: string;
  thenKeys?: string[];
}

/** The action a classifier recommends; the host reactor branches only on these generic fields. */
export interface TabStateAction {
  /** Key names to inject, e.g. ["down", "enter"]. */
  keys?: string[];
