}

// ── surfaces (plugin.json `capabilities.surfaces`; core owns the tab frame) ──

// `view` renders the plugin's `ui/index.html` and requires `capabilities.view`.
export type SurfaceRenderer = "view" | "stream";
export type SurfaceRestore = "relaunch" | "placeholder" | "none";

/** Host-injected iframe bridge; state subscriptions are hints, not a polling API. */
export interface SurfaceViewBridge {
  surface: { surface: string | null; instance: string | null; tab: string | null };
  invoke(method: string, args?: unknown): Promise<unknown>;
  close(): void;
  onSurfaceStateChanged(callback: () => void): () => void;
}

export interface SurfaceCallContext {
  surface: string;
  instance: string;
  tab: string;
  owner: string;
  /** Authenticated calling agent tab id, stamped by the host. */
  actor: string;
  /** Sanitized display label; attribution uses actor, never this label as authority. */
  actorLabel: string;
}

export interface SurfaceAgentHandler {
  onSurfaceCall(context: SurfaceCallContext, verb: string, args: string[]): string;
}

export interface SurfaceContribution {
  /** View only: at most 32 unique lowercase kebab verbs, each at most 32 bytes. */
  agentVerbs?: string[];
  /** View only: permit identity-only state invalidation through host.surface.invalidate. */
  stateInvalidation?: boolean;
  // 1-32 lowercase letters, digits or '-', unique within the plugin.
  id: string;
  // One word, no whitespace: the tab title.
  title: string;
  renderer: SurfaceRenderer;
  // Opened under an owner agent; the UI labels it "{owner}'s {title}".
  agentBound?: boolean;
  restore?: SurfaceRestore;
  // Required for `stream`: the core surface runtime that renders it (e.g. "browser").
  runtime?: string;
  // Toolbar spec passed through untouched to the frontend; `stream` only.
  chrome?: Record<string, unknown>;
}

// ── viewHostActions (plugin.json `capabilities.viewHostActions`; requires `view`) ──

// The user-gesture actions the view page may ask for through `ct.host`; each named once.
export type ViewHostAction = "copyText" | "saveAs" | "reveal";

// `denied`: no recent activation in this shown, focused view; undeclared; cancelled; `busy` (one
// call at a time, at most one effect per second); `stale` (the frame was hidden or replaced
// meanwhile); or media this frame does not own.
// `unavailable`: the host cannot act here (the web mirror has no file manager).
// `invalid`: malformed text, handle or arguments.
export type ViewHostResult = { ok: true } | { ok: false; code: "denied" | "unavailable" | "invalid"; reason: string };

// What this app instance can perform here (the web mirror has no file manager, an insecure origin no
// clipboard). It grants nothing: the declaration, gesture and media ownership are checked on each use.
export type ViewHostAvailability = Record<ViewHostAction, boolean>;

// `window.ct.host` inside the view page. Call the actions from a click or key handler: the host checks
// its own user activation. Media handles are the host-issued ones this frame received; never paths.
export interface ViewHostBridge {
  // Resolves once the host has said what it supports; read it to hide an action, never to probe one.
  availability(): Promise<ViewHostAvailability>;
  copyText(text: string): Promise<ViewHostResult>;
  saveAs(mediaHandle: string, suggestedName?: string): Promise<ViewHostResult>;
  reveal(mediaHandle: string): Promise<ViewHostResult>;
}

// ── onAgentCommand (the inverse seam) ──

export interface AgentCommandCtx {
  body?: string;
  sessionId: string;
  verb: string;
  args: string[];
}

export interface AgentCommandHandler {
  onAgentCommand(ctx: AgentCommandCtx): { result: string; catalogueChanged?: boolean } | { error: string };
}

// ── The default-export shape: every capability method optional ──

export interface PluginModule
  extends Partial<AgentProvider>,
    Partial<AgentRuntime>,
    Partial<SecretBackend>,
    Partial<Transcriber>,
    Partial<Converter>,
    Partial<DecisionModelCapability>,
    Partial<ChatBackend>,
    Partial<ChatPreprocessor>,
    Partial<WebhookReceiver>,
    Partial<AgentCommandHandler>,
    Partial<SurfaceAgentHandler>,
    Partial<ModelProviderConfig> {
  onPermissionChanged?(event: PermissionChangedEvent): void | { error: string };
  statusBubble?(ctx: TabContext): StatusBubble | null;
  renderGlance?(ctx: TabContext): GlanceView;
  viewCall?: ViewCall;
  /** Requires manifest mediaDelivery. Lookup only: never submit work. Paths are relative to this plugin's own data directory. */
  mediaFile?(id: string): import("./mediaDelivery").MediaFile;
  /** Refresh account-backed remote execution availability and environments. */
  discoverRemoteTask?(): import("./remoteTasks").RemoteTaskDiscovery;
  glanceAction?(action: string, ctx: TabContext): unknown;
  // Test-only exports and other plugin-private members are allowed.
  [key: string]: unknown;
}

export interface PermissionChangedEvent {
  permission: string;
  allowed: true;
  source: "install" | "action" | "settings";
}

/** Manifest capabilities.mediaDelivery, available only with a view. */
export interface MediaDeliveryDescriptor { types: MediaContentType[]; }
export type MediaContentType = "video/mp4" | "video/webm" | "video/ogg" | "audio/mpeg" | "audio/ogg" | "audio/wav" | "image/png" | "image/jpeg" | "image/webp" | "image/gif";
/** Backend-only mediaFile(id) result. The frame never supplies or receives this path. */
export interface MediaFile { path: string; contentType: MediaContentType; fileName?: string; }
/** ct.media(id) result in an iframe. Image handles are usable by gesture actions; playback URL is null. */
export interface PluginMediaHandle { handle: string; url: string | null; content_type: MediaContentType; file_name: string; expires_in_seconds: number; }

import { invokePluginWithConsent } from "../../lib/pluginConsent";
/**
 * Host for a plugin's iframe UI (the `view` capability). Renders the plugin's
 * `ui/index.html` in a sandboxed iframe (origin-null, CSP-locked) and relays the
 * `ct.invoke` postMessage bridge to the permission-gated `plugin_view_call`.
 *
 * The iframe holds no capability: its only channel is postMessage to us, and we
 * forward each call to the host (which stamps the plugin id + checks permissions).
 */
import { useCallback, useEffect, useRef, useState, type CSSProperties } from "react";
import { listen, type UnlistenFn } from "../../lib/bridge";
import { type DaemonApiConfig } from "../../lib/webApi";
import { PluginUiHost } from "./PluginUiHost";
import { pluginUiDocumentState, pluginUiHostTransition, pluginUiRuntimeEvent, type PluginUiHostState } from "../../lib/pluginUiHostModel";
import { usePluginDocument } from "./usePluginDocument";
import { invalidatePluginBubble } from "../../lib/pluginBubbleCache";
import { KPI_CHANGE_NOTICE, KPI_RECORDED_EVENT } from "../../lib/kpiChanges";
import { DEFAULT_THEME, themeToCSS } from "../../lib/themeCss";
import { surfaceInvalidationMatches } from "../../lib/surfaceInvalidation";
import { surfaceQuery, type PluginViewSurface } from "../../lib/surfaceTab";
import { createViewHostGate, performViewHostAction, viewHostSupport, type ViewHostGate } from "../../lib/pluginViewHostActions";
import { viewHostDeps } from "../../lib/pluginViewHostDeps";
import { getPluginSnapshotState } from "../../lib/pluginSnapshotStore";

type ApiCfg = DaemonApiConfig;

/** How long the host's "Copied from …" receipt stays on the view. */
const COPY_NOTICE_MS = 2500;
const COPY_NOTICE_STYLE: CSSProperties = {
  position: "absolute",
  left: "50%",
  bottom: 12,
  transform: "translateX(-50%)",
  padding: "4px 10px",
  borderRadius: 999,
  background: "var(--ct-bg-elev, var(--ct-surface))",
  border: "1px solid var(--ct-border-default, rgba(255,255,255,0.12))",
  color: "var(--ct-fg)",
  fontSize: "var(--ct-font-size-sm, 0.8125rem)",
  whiteSpace: "nowrap",
  pointerEvents: "none",
};

/** Every theme token the app derives, so shared components render inside a plugin UI as they do in the app. */
export const PLUGIN_THEME_VARS = Object.keys(themeToCSS(DEFAULT_THEME));

function themeCss(): string {
  const cs = getComputedStyle(document.documentElement);
  return PLUGIN_THEME_VARS.map((v) => `${v}:${cs.getPropertyValue(v).trim()}`)
    .filter((s) => !s.endsWith(":"))
    .join(";");
}

export function PluginView({
  pluginId,
  api: _api,
  onClose,
  embedded,
  cwd,
  active = true,
  focusOnActive = false,
  kpiNotices = false,
  surface,
}: {
  pluginId: string;
  api: ApiCfg | undefined;
  onClose?: () => void;
  /** Render just the iframe (no fullscreen chrome) to embed in a detail panel. */
  embedded?: boolean;
  /** Tab cwd stamped into view-call args that omit one (e.g. the Git panel). */
  cwd?: string | null;
  /** A kept-mounted view that is hidden ignores Escape; the iframe hears `__ctActive` on each change. */
  active?: boolean;
  focusOnActive?: boolean;
  /** Forward KPI ledger commits while shown; a hidden view catches up from its `__ctActive` notice. */
  kpiNotices?: boolean;
  /** Set when the view renders a surface tab; the page reads it from its query string. */
  surface?: PluginViewSurface;
}) {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const activeRef = useRef(active);
  activeRef.current = active;
  const [runtime, setRuntime] = useState<{ path: string; state: PluginUiHostState } | null>(null);
  // Host actions are fenced by a document generation that only ever grows: hiding the view, a new
  // document, any load of the frame (reload or navigation keeps the same WindowProxy) and unmount
  // end every pending request, which never becomes current again. Each generation gets its own gate.
  const generationRef = useRef(0);
  const hostGate = useRef<ViewHostGate>(createViewHostGate());
  const invalidateHostActions = useCallback(() => {
    generationRef.current += 1;
    hostGate.current = createViewHostGate();
  }, []);
  // The host's own, non-suppressible receipt for a clipboard write the plugin asked for.
  // A fresh object per copy, so a repeated copy restarts the notice instead of being swallowed.
  const [copiedFrom, setCopiedFrom] = useState<{ name: string } | null>(null);
  const announceCopy = useCallback(() => {
    const plugin = getPluginSnapshotState().snapshot.plugins.find((item) => item.id === pluginId);
    setCopiedFrom({ name: plugin?.display_name || pluginId });
  }, [pluginId]);
  useEffect(() => {
    if (!copiedFrom) return;
    const timer = setTimeout(() => setCopiedFrom(null), COPY_NOTICE_MS);
    return () => clearTimeout(timer);
  }, [copiedFrom]);
  useEffect(() => {
    if (!active) invalidateHostActions();
  }, [active, invalidateHostActions]);

  // A hot-reloaded plugin ships a new bundle, but the iframe keeps the one it
  // already loaded until its src changes, so the reload has to bust it.
  const [reloadNonce, setReloadNonce] = useState(0);
  useEffect(() => {
    let alive = true;
    let unlisten: UnlistenFn | undefined;
    listen<{ kind: string }>("contributions-changed", (event) => {
      if (alive && event.payload.kind === `plugin_view:${pluginId}`) {
        setReloadNonce((n) => n + 1);
      }
    })
      .then((fn) => {
        if (alive) unlisten = fn;
        else fn();
      })
      .catch(() => undefined);
    return () => {
      alive = false;
      unlisten?.();
    };
  }, [pluginId]);

  useEffect(() => {
    if (!surface) return;
    let alive = true;
    let unlisten: UnlistenFn | undefined;
    listen<unknown>("surface-state-invalidated", (event) => {
      if (alive && surfaceInvalidationMatches(event.payload, pluginId, surface)) {
        iframeRef.current?.contentWindow?.postMessage({ __ctSurfaceStateChanged: true }, "*");
      }
    }).then((release) => {
      if (alive) unlisten = release;
      else release();
    }).catch(() => undefined);
    return () => { alive = false; unlisten?.(); };
  }, [pluginId, surface?.surfaceId, surface?.instanceId, surface?.tabId]);

  const path = `/api/plugins/${encodeURIComponent(pluginId)}/ui/index.html${surfaceQuery(surface).replace(/^&/, "?")}`;
  const documentPath = `${path}${path.includes("?") ? "&" : "?"}reload=${reloadNonce}`;
  const { html, media, dispose: disposeDocument, frameToken, error: documentError } = usePluginDocument(documentPath);
  useEffect(() => invalidateHostActions, [documentPath, frameToken, invalidateHostActions]);
  const state = pluginUiDocumentState(html, documentError, runtime?.path === documentPath ? runtime.state : { status: "loading" });

  const onMessage = useCallback(
    async (e: MessageEvent) => {
      const win = iframeRef.current?.contentWindow;
      if (!win || e.source !== win) return; // only our iframe
      const m = e.data || {};
      const event = pluginUiRuntimeEvent(m.__ctUiState);
      if (event) {
        setRuntime((current) => ({ path: documentPath, state: pluginUiHostTransition(current?.path === documentPath ? current.state : { status: "loading" }, event) }));
        return;
      }
      if (m.__ctReady) {
        win.postMessage({ __ctTheme: themeCss() }, "*");
        win.postMessage({ __ctActive: activeRef.current }, "*");
        win.postMessage({ __ctHostSupport: viewHostSupport(viewHostDeps()) }, "*");
        if (surface) win.postMessage({ __ctSurfaceStateChanged: true }, "*");
        return;
      }
      if (m.__ctClose) {
        onClose?.();
        return;
      }
      if (m.__ctHost != null) {
        // Observed by the app before any await, never taken from the frame.
        const intent = {
          shown: activeRef.current,
          frameFocused: iframeRef.current !== null && document.activeElement === iframeRef.current,
          activated: globalThis.navigator?.userActivation?.isActive === true,
        };
        // The request belongs to this document generation; hide, reload, navigation and disposal end it for good.
        const generation = generationRef.current;
        const isCurrent = () => generationRef.current === generation && iframeRef.current?.contentWindow === win && activeRef.current;
        const deps = viewHostDeps();
        const writeText = deps.writeText;
        const announced = writeText && {
          ...deps,
          writeText: async (text: string) => {
            await writeText(text);
            announceCopy();
          },
        };
        const result = await performViewHostAction(pluginId, frameToken ?? null, m, intent, announced || deps, isCurrent, hostGate.current);
        if (isCurrent()) win.postMessage({ __ctReply: m.__ctHost, result }, "*");
        return;
      }
      if (m.__ctMedia != null) {
        try {
          if (!media || !Number.isSafeInteger(m.__ctMedia) || typeof m.id !== "string") throw new Error("Plugin media unavailable");
          const result = await media(m.id);
          if (iframeRef.current?.contentWindow === win) win.postMessage({ __ctReply: m.__ctMedia, result }, "*");
        } catch {
          if (iframeRef.current?.contentWindow === win) win.postMessage({ __ctReply: m.__ctMedia, error: "Plugin media unavailable" }, "*");
        }
        return;
      }
      if (m.__ctInvoke != null) {
        try {
          // iframes (e.g. Git) never need to know their own path.
          const args =
            cwd && m.args && typeof m.args === "object" && (m.args as { cwd?: unknown }).cwd == null
              ? { ...m.args, cwd }
              : m.args;
          const result = await invokePluginWithConsent("plugin_view_call", { pluginId, method: m.method, args }, () => iframeRef.current?.contentWindow === win);
          if (iframeRef.current?.contentWindow !== win) return;
          // In-panel actions invalidate their bubble immediately.
          const usedCwd = (args as { cwd?: unknown } | undefined)?.cwd;
          if (typeof usedCwd === "string") invalidatePluginBubble(pluginId, usedCwd);
          win.postMessage({ __ctReply: m.__ctInvoke, result }, "*");
        } catch (err) {
          if (iframeRef.current?.contentWindow !== win) return;
          win.postMessage({ __ctReply: m.__ctInvoke, error: String(err) }, "*");
        }
      }
    },
    [pluginId, cwd, onClose, documentPath, surface, media, frameToken, announceCopy],
  );

  useEffect(() => {
    window.addEventListener("message", onMessage);
    return () => window.removeEventListener("message", onMessage);
  }, [onMessage]);

  useEffect(() => {
    if (!kpiNotices) return;
    let alive = true;
    let unlisten: UnlistenFn | undefined;
    listen(KPI_RECORDED_EVENT, () => {
      if (activeRef.current) iframeRef.current?.contentWindow?.postMessage({ [KPI_CHANGE_NOTICE]: true }, "*");
    })
      .then((fn) => {
        if (alive) unlisten = fn;
        else fn();
      })
      .catch(() => undefined);
    return () => {
      alive = false;
      unlisten?.();
    };
  }, [kpiNotices]);

  useEffect(() => {
    iframeRef.current?.contentWindow?.postMessage({ __ctActive: active }, "*");
    if (active && focusOnActive && !embedded && state.status === "ready") iframeRef.current?.focus();
  }, [active, focusOnActive, embedded, state.status]);

  // Universal escape (host-side focus); in-iframe Esc/close routes via __ctClose.
  useEffect(() => {
    if (embedded || !active) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose?.();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [active, embedded, onClose]);

  const loadedDocument = useRef<string | null>(null);
  const frame = (
    <PluginUiHost pluginId={pluginId} state={state} onRetry={() => setReloadNonce((n) => n + 1)}>
      {html !== undefined && html.trim() && <iframe
        key={documentPath}
        ref={iframeRef}
        data-testid="extensions-plugin-iframe"
        data-plugin-id={pluginId}
        srcDoc={html}
        onLoad={() => {
          invalidateHostActions();
          if (loadedDocument.current === documentPath) {
            disposeDocument?.();
            setReloadNonce((nonce) => nonce + 1);
          }
          loadedDocument.current = documentPath;
        }}
        title={`${pluginId} view`}
        sandbox="allow-scripts"
        style={{ flex: 1, width: "100%", border: "none", background: "var(--ct-bg)", display: "block", height: "100%" }}
      />}
      {copiedFrom && <div role="status" data-testid="plugin-view-copied" style={COPY_NOTICE_STYLE}>Copied from {copiedFrom.name}</div>}
    </PluginUiHost>
  );

  if (embedded) {
    return (
      <div
        data-testid="extensions-plugin-embedded-view"
        data-plugin-id={pluginId}
        style={{
          width: "100%",
          height: 360,
          display: "flex",
          borderRadius: 8,
          overflow: "hidden",
          background: "var(--ct-bg)",
          border: "1px solid var(--ct-border-subtle, rgba(255,255,255,0.08))",
        }}
      >
        {frame}
      </div>
    );
  }

  return (
    <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", background: "var(--ct-bg)" }}>
      {frame}
    </div>
  );
}

import { useEffect, useState } from "react";
import { baseDaemonTransport } from "../../lib/daemonBootstrap";
import { loadPluginDocument, type PluginDocument } from "../../lib/pluginDocument";

export function usePluginDocument(path: string): { html: string | undefined; error: string | null; media?: PluginDocument["media"]; dispose?: () => void; frameToken?: string | null } {
  const [state, setState] = useState<{ path: string; html?: string; error: string | null; media?: PluginDocument["media"]; dispose?: () => void; frameToken?: string | null }>({ path, error: null });
  useEffect(() => {
    const controller = new AbortController();
    let dispose: (() => void) | undefined;
    void loadPluginDocument(baseDaemonTransport(), path, controller.signal).then((document) => {
      if (controller.signal.aborted) { document.dispose(); return; }
      dispose = document.dispose;
      setState({ path, html: document.html, media: document.media, frameToken: document.frameToken, dispose: document.dispose, error: null });
    }).catch((error: unknown) => {
      if (!controller.signal.aborted) setState({ path, error: String(error) });
    });
    return () => { controller.abort(); dispose?.(); };
  }, [path]);
  return state.path === path ? { html: state.html, error: state.error, media: state.media, frameToken: state.frameToken, dispose: state.dispose } : { html: undefined, error: null };
}

import { PLUGIN_UI_MONITOR } from "./pluginUiMonitor";
import { parse } from "es-module-lexer/js";
import type { TransportClient } from "./transportClient";

export const MAX_PLUGIN_DOCUMENT_BYTES = 8 * 1024 * 1024;

export interface PluginMediaHandle {
  handle: string;
  url: string | null;
  content_type: string;
  file_name: string;
  expires_in_seconds: number;
}

export interface PluginDocument {
  html: string;
  frameToken: string | null;
  dispose(): void;
  media(id: string): Promise<PluginMediaHandle>;
}

export interface PluginAsset {
  bytes: Uint8Array;
  mime: string;
}

export function pluginAssetPath(reference: string, documentPath: string, origin: string): string {
  const documentUrl = new URL(documentPath, origin);
  const url = new URL(reference, documentUrl);
  if (!/^\/api\/plugins\/[^/]+\/ui\//.test(documentUrl.pathname)) throw new Error("Plugin UI document path required");
  const root = documentUrl.pathname.slice(0, documentUrl.pathname.indexOf("/ui/") + 4);
  if (url.origin !== origin || !url.pathname.startsWith(root) || url.search || url.hash || url.username || url.password) {
    throw new Error("Plugin asset must stay within its UI directory without credentials");
  }
  return url.pathname;
}

function bounded(text: string): string {
  if (new TextEncoder().encode(text).byteLength > MAX_PLUGIN_DOCUMENT_BYTES) {
    throw new Error("Plugin document exceeds 8 MiB limit");
  }
  return text;
}

function dataUrl(asset: PluginAsset): string {
  if (!/^(image\/|font\/)/.test(asset.mime)) throw new Error("Plugin data assets must be images or fonts");
  let binary = "";
  for (let offset = 0; offset < asset.bytes.length; offset += 32768) {
    binary += String.fromCharCode(...asset.bytes.subarray(offset, offset + 32768));
  }
  return `data:${asset.mime};base64,${btoa(binary)}`;
}

export async function materializePluginDocument(
  raw: string, policy: string, path: string, origin: string,
  readAsset: (path: string) => Promise<PluginAsset>,
): Promise<string> {
  const scripts = policy.split(";").map((directive) => directive.trim()).find((directive) => directive.startsWith("script-src "));
  const nonce = scripts?.match(/^script-src 'nonce-([A-Za-z0-9+/_=-]+)'$/)?.[1];
  if (!nonce) throw new Error("Plugin document nonce security policy required");
  const document = new DOMParser().parseFromString(bounded(raw), "text/html");
  let totalBytes = new TextEncoder().encode(raw).byteLength;
  const asset = async (reference: string, parentPath = path) => {
    const result = await readAsset(pluginAssetPath(reference, parentPath, origin));
    totalBytes += result.bytes.byteLength;
    if (totalBytes > MAX_PLUGIN_DOCUMENT_BYTES) throw new Error("Plugin document exceeds 8 MiB limit");
    return result;
  };
  const cssAssets = async (css: string, parentPath: string) => {
    if (/@import\b/i.test(css)) throw new Error("Plugin stylesheets must be self-contained (no @import)");
    for (const match of [...css.matchAll(/url\(\s*(["']?)([^"')]+)\1\s*\)/g)]) {
      const reference = match[2].trim();
      if (reference.startsWith("data:") || reference.startsWith("#")) continue;
      css = css.replace(match[0], `url("${dataUrl(await asset(reference, parentPath))}")`);
    }
    return css;
  };
  for (const script of document.querySelectorAll("script")) {
    if ((script.nonce || script.getAttribute("nonce")) !== nonce) throw new Error("Plugin script nonce does not match document policy");
    const reference = script.getAttribute("src");
    const source = reference === null ? script.textContent ?? "" : new TextDecoder().decode((await asset(reference)).bytes);
    const [imports] = await parse(source);
    if (imports.length) throw new Error("Plugin scripts must be self-contained (no chunk imports or import.meta)");
    // Raw-text HTML parsing must not let a JavaScript string close its script element.
    script.textContent = source.replace(/<!--/g, "\\x3c!--").replace(/<\/script/gi, (closing) => `<\\/${closing.slice(2)}`);
    script.setAttribute("nonce", nonce);
    script.removeAttribute("src");
    script.removeAttribute("integrity");
    script.removeAttribute("crossorigin");
    script.removeAttribute("async");
    script.removeAttribute("defer");
  }
  for (const image of document.querySelectorAll("img[src]")) {
    const reference = image.getAttribute("src")!;
    if (!reference.startsWith("data:")) image.setAttribute("src", dataUrl(await asset(reference)));
  }
  for (const link of document.querySelectorAll("link[href]")) {
    if (link.getAttribute("rel")?.toLowerCase() !== "stylesheet") throw new Error("Unsupported plugin document link");
    const reference = link.getAttribute("href")!;
    const parentPath = pluginAssetPath(reference, path, origin);
    const stylesheet = await asset(reference);
    if (stylesheet.mime !== "text/css") throw new Error("Plugin stylesheet MIME required");
    const style = document.createElement("style");
    if (link.hasAttribute("media")) style.setAttribute("media", link.getAttribute("media")!);
    style.textContent = await cssAssets(new TextDecoder().decode(stylesheet.bytes), parentPath);
    link.replaceWith(style);
  }
  for (const style of document.querySelectorAll("style")) {
    style.textContent = await cssAssets(style.textContent ?? "", path);
  }
  const monitor = document.createElement("script");
  monitor.setAttribute("nonce", nonce);
  monitor.setAttribute("data-plugin-ui-monitor", "");
  monitor.textContent = PLUGIN_UI_MONITOR;
  document.head.prepend(monitor);
  const meta = document.createElement("meta");
  meta.httpEquiv = "Content-Security-Policy";
  meta.content = policy;
  document.head.prepend(meta);
  return bounded("<!doctype html>" + document.documentElement.outerHTML);
}

export async function loadPluginDocument(client: TransportClient, path: string, signal: AbortSignal): Promise<PluginDocument> {
  const request = async (assetPath: string) => {
    const response = await client.request!(assetPath, { signal }, true);
    if (!response.ok) {
      const reason = (await response.text()).slice(0, 1000).trim();
      throw new Error(`Plugin asset HTTP ${response.status} (${assetPath})${reason ? `: ${reason}` : ""}`);
    }
    return response;
  };
  const response = await request(path);
  const policy = response.headers.get("Content-Security-Policy");
  if (!policy) throw new Error("Plugin document security policy missing");
  const frame = response.headers.get("X-Domios-Plugin-Media-Frame");
  const plugin = new URL(path, client.origin()).pathname.match(/^\/api\/plugins\/([a-z0-9_-]{1,128})\/ui\//)?.[1];
  if (frame !== null && (!/^[a-f0-9]{64}$/.test(frame) || !plugin)) throw new Error("Invalid plugin media frame");
  const base = frame && plugin ? `/api/plugins/${plugin}` : null;
  let disposed = false;
  const dispose = () => {
    if (disposed) return;
    disposed = true;
    if (base) void client.request!(`${base}/media-frame/${frame}`, { method: "DELETE", keepalive: true }, true).catch(() => undefined);
  };
  try {
    const mediaPolicy = base
      ? policy.replace(/(?:^|;\s*)media-src 'none'(?=;|$)/, (directive) => directive.replace("'none'", `${new URL(`${base}/media/${frame}/`, client.origin()).href} blob:`))
      : policy;
    if (base && mediaPolicy === policy) throw new Error("Plugin media security policy missing");
    const html = await materializePluginDocument(await response.text(), mediaPolicy, path, client.origin(), async (assetPath) => {
      const asset = await request(assetPath);
      return { bytes: new Uint8Array(await asset.arrayBuffer()), mime: asset.headers.get("Content-Type")?.split(";")[0].trim() ?? "" };
    });
    signal.throwIfAborted();
    return { html, frameToken: frame, dispose, async media(id) {
      if (disposed || signal.aborted || !base || typeof id !== "string" || !id || id.length > 256) throw new Error("Plugin media unavailable");
      const result = await client.localJson<PluginMediaHandle>("POST", `${base}/media-register/${frame}`, { id }, { signal });
      if (disposed || signal.aborted) throw new Error("Plugin media unavailable");
      if (!/^[a-f0-9]{64}$/.test(result.handle)) throw new Error("Invalid plugin media handle");
      const expected = `${base}/media/${frame}/${result.handle}`;
      if (result.url !== null && result.url !== expected) throw new Error("Invalid plugin media URL");
      return { ...result, url: result.url === null ? null : new URL(expected, client.origin()).href };
    } };
  } catch (error) { dispose(); throw error; }
}

import type { SurfaceTabBacking, Tab, TabBacking } from "./types";

export type TabBody = "surface_view" | "chat_backend" | "terminal";

export function surfaceBacking(tab: { backing?: TabBacking } | null | undefined): SurfaceTabBacking | null {
  return tab?.backing?.kind === "surface" ? tab.backing : null;
}

export function isSurfaceTab(tab: { backing?: TabBacking } | null | undefined): boolean {
  return surfaceBacking(tab) !== null;
}

/** A tab without a backing predates the field and is a PTY. */
export function isPtyBacked(tab: { backing?: TabBacking }): boolean {
  return tab.backing == null || tab.backing.kind === "pty";
}

export function tabBody(tab: { backing?: TabBacking }): TabBody {
  switch (tab.backing?.kind) {
    case "surface":
      return "surface_view";
    case "chat_backend":
      return "chat_backend";
    default:
      return "terminal";
  }
}

/** Surface tabs take no text: actions go through the plugin's verbs. */
export function canSendText(tab: { backing?: TabBacking }): boolean {
  return !isSurfaceTab(tab);
}

/** "{Owner}'s {Title}" when the surface asks for its owner's name and the owner is known. */
export function surfaceDisplayLabel(title: string, backing: SurfaceTabBacking, ownerName: string | null | undefined): string {
  const owner = ownerName?.trim();
  return backing.owner_label && owner ? `${owner}'s ${title}` : title;
}

export function surfaceOwnerId(tab: Pick<Tab, "parent_tab_id">): string | null {
  return tab.parent_tab_id ?? null;
}

/** Identity a surface tab hands its plugin view. */
export interface PluginViewSurface {
  surfaceId: string;
  instanceId: string;
  tabId: string;
}

export function pluginViewSurface(tabId: string, backing: SurfaceTabBacking): PluginViewSurface {
  return { surfaceId: backing.surface_id, instanceId: backing.instance_id, tabId };
}

/** Query suffix for the authenticated document request; the page reads `ct.surface`. */
export function surfaceQuery(surface: PluginViewSurface | undefined): string {
  if (!surface) return "";
  const params = new URLSearchParams({ surface: surface.surfaceId, instance: surface.instanceId, tab: surface.tabId });
  return `&${params.toString()}`;
}

export function workspaceIdOfTab(workspaces: readonly { id: string; tabs: readonly string[] }[], tabId: string | null | undefined): string | null {
  if (!tabId) return null;
  return workspaces.find((workspace) => workspace.tabs.includes(tabId))?.id ?? null;
}

/** The owner's title a sidebar row composes into its label; null when the row is not an owner-labelled surface. */
export function surfaceOwnerTitle(tab: Tab, tabs: Readonly<Record<string, Pick<Tab, "title">>>): string | null {
  const backing = surfaceBacking(tab);
  if (!backing?.owner_label || !tab.parent_tab_id) return null;
  return tabs[tab.parent_tab_id]?.title ?? null;
}

/** The label a tab row shows: surfaces compose their owner's name, every other tab keeps its title. */
export function tabRowLabel(tab: Tab, title: string, ownerTitle: string | null | undefined): string {
  const backing = surfaceBacking(tab);
  return backing ? surfaceDisplayLabel(title, backing, ownerTitle) : title;
}

import { useCallback, useSyncExternalStore } from "react";

export const SURFACE_ACTIVITY_EVENT = "surface-activity";
/** One droplet pass; matches --ct-duration-liquid-sweep. */
export const SURFACE_PULSE_MS = 560;
/** How long a visiting agent's name stays on the surface after its last verb. */
export const SURFACE_ACTOR_LINGER_MS = 4000;
const MAX_ACTOR = 48;

export interface SurfaceActivityPayload {
  tab_id: string;
  verb: string;
  /** The acting agent, present only when it is not the surface owner. */
  actor?: string;
}

export interface SurfacePulse {
  nonce: number;
  verb: string;
}

export function parseSurfaceActivity(payload: unknown): SurfaceActivityPayload | null {
  if (typeof payload !== "object" || payload === null) return null;
  const { tab_id, verb, actor } = payload as Record<string, unknown>;
  if (typeof tab_id !== "string" || !tab_id) return null;
  const parsed: SurfaceActivityPayload = { tab_id, verb: typeof verb === "string" ? verb : "" };
  const name = typeof actor === "string" ? actor.trim().slice(0, MAX_ACTOR) : "";
  if (name) parsed.actor = name;
  return parsed;
}

export interface SurfaceActivityStore {
  record(payload: unknown): void;
  pulse(tabId: string): SurfacePulse | null;
  actor(tabId: string): string | null;
  subscribe(listener: () => void): () => void;
  reset(): void;
}

export function createSurfaceActivityStore(durationMs = SURFACE_PULSE_MS, actorLingerMs = SURFACE_ACTOR_LINGER_MS): SurfaceActivityStore {
  const pulses = new Map<string, SurfacePulse>();
  const timers = new Map<string, ReturnType<typeof setTimeout>>();
  const actors = new Map<string, string>();
  const actorTimers = new Map<string, ReturnType<typeof setTimeout>>();
  const dropActor = (tabId: string) => {
    const pending = actorTimers.get(tabId);
    if (pending) clearTimeout(pending);
    actorTimers.delete(tabId);
    actors.delete(tabId);
  };
  const listeners = new Set<() => void>();
  let nonce = 0;
  const emit = () => {
    for (const listener of listeners) listener();
  };
  return {
    record(payload) {
      const activity = parseSurfaceActivity(payload);
      if (!activity) return;
      const { tab_id: tabId, verb, actor } = activity;
      dropActor(tabId);
      if (actor) {
        actors.set(tabId, actor);
        actorTimers.set(tabId, setTimeout(() => {
          actorTimers.delete(tabId);
          actors.delete(tabId);
          emit();
        }, actorLingerMs));
      }
      nonce += 1;
      pulses.set(tabId, { nonce, verb });
      const pending = timers.get(tabId);
      if (pending) clearTimeout(pending);
      timers.set(tabId, setTimeout(() => {
        timers.delete(tabId);
        pulses.delete(tabId);
        emit();
      }, durationMs));
      emit();
    },
    pulse: (tabId) => pulses.get(tabId) ?? null,
    actor: (tabId) => actors.get(tabId) ?? null,
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    reset() {
      for (const timer of timers.values()) clearTimeout(timer);
      timers.clear();
      pulses.clear();
      for (const timer of actorTimers.values()) clearTimeout(timer);
      actorTimers.clear();
      actors.clear();
      emit();
    },
  };
}

export const surfaceActivityStore = createSurfaceActivityStore();

export function recordSurfaceActivity(payload: unknown): void {
  surfaceActivityStore.record(payload);
}

/** The pass in flight for a surface tab, or null once it has landed. */
export function useSurfacePulse(surfaceTabId: string | null | undefined, store: SurfaceActivityStore = surfaceActivityStore): SurfacePulse | null {
  const read = useCallback(() => (surfaceTabId ? store.pulse(surfaceTabId) : null), [store, surfaceTabId]);
  return useSyncExternalStore(store.subscribe, read, read);
}

/** The non-owner agent acting on a surface tab right now, or null. */
export function useSurfaceActor(surfaceTabId: string | null | undefined, store: SurfaceActivityStore = surfaceActivityStore): string | null {
  const read = useCallback(() => (surfaceTabId ? store.actor(surfaceTabId) : null), [store, surfaceTabId]);
  return useSyncExternalStore(store.subscribe, read, read);
}

import type { PluginViewSurface } from "./surfaceTab";

/** Old instances, another plugin and another surface never refresh this frame. */
export function surfaceInvalidationMatches(payload: unknown, plugin: string, surface: PluginViewSurface): boolean {
  if (!payload || typeof payload !== "object") return false;
  const value = payload as Record<string, unknown>;
  return value.plugin === plugin && value.surface === surface.surfaceId
    && value.instance === surface.instanceId && value.tab === surface.tabId;
}

/**
 * `ct.host.*` user-gesture actions a plugin view asks the app for.
 *
 * The iframe is untrusted: it names an action and its arguments, nothing else.
 * The app supplies everything that carries authority — the plugin id, the
 * host-held frame token and the user intent it observes itself (see
 * `ViewHostIntent`). The daemon then enforces the manifest declaration and
 * media ownership. Every outcome is a typed result; nothing throws into the frame.
 */

export const VIEW_HOST_ACTIONS = ["copyText", "saveAs", "reveal"] as const;
export type ViewHostActionName = (typeof VIEW_HOST_ACTIONS)[number];
export type ViewHostRefusalCode = "denied" | "unavailable" | "invalid";
export type ViewHostResult = { ok: true } | { ok: false; code: ViewHostRefusalCode; reason: string };

/** Longest text a view may put on the clipboard in one call. */
export const MAX_COPY_TEXT = 100_000;
const MAX_FILE_NAME = 120;

export interface ViewHostMediaRequest {
  pluginId: string;
  frame: string | null;
  handle: string;
}

export interface ViewHostDeps {
  /** `POST /api/plugins/view-host-action`; the daemon's typed answer. */
  call(request: Record<string, unknown>): Promise<unknown>;
  /** The clipboard; absent where the page has none (an insecure web mirror origin). */
  writeText?: (text: string) => Promise<void>;
  /** The native save dialog; absent where the app cannot write a local file (web mirror, relayed peer). */
  pickDestination?: (suggestedName: string) => Promise<string | null>;
  /** Saves through the browser instead of a dialog; hands the file over only while `isCurrent()`. */
  download(request: ViewHostMediaRequest, fileName: string, isCurrent: () => boolean): Promise<ViewHostResult>;
  /** The native file manager; absent on the web mirror and a relayed peer. */
  reveal?: (path: string) => Promise<void>;
}

const refused = (code: ViewHostRefusalCode, reason: string): ViewHostResult => ({ ok: false, code, reason });

export type ViewHostSupport = Record<ViewHostActionName, boolean>;

/**
 * What this app instance can perform for a view, sent once when the frame is ready so a view can
 * hide an action instead of probing it. It grants nothing: declaration, gesture and media
 * ownership are still checked on every use.
 */
export function viewHostSupport(deps: Pick<ViewHostDeps, "writeText" | "reveal">): ViewHostSupport {
  return { copyText: deps.writeText !== undefined, saveAs: true, reveal: deps.reveal !== undefined };
}

function record(value: unknown): Record<string, unknown> | null {
  return typeof value === "object" && value !== null && !Array.isArray(value) ? value as Record<string, unknown> : null;
}

/** Narrow whatever the daemon answered to the typed result; anything else is the host being unavailable. */
export function viewHostResult(value: unknown): ViewHostResult & { path?: string } {
  const body = record(value);
  if (body?.ok === true) return typeof body.path === "string" ? { ok: true, path: body.path } : { ok: true };
  const code = body?.code;
  if (body?.ok === false && (code === "denied" || code === "unavailable" || code === "invalid") && typeof body.reason === "string") {
    return refused(code, body.reason.slice(0, 64));
  }
  return refused("unavailable", "host");
}

/** A file name the user sees in a dialog or download: no separators, controls or reserved characters. */
export function safeFileName(raw: unknown): string {
  const cleaned = (typeof raw === "string" ? raw : "")
    .replace(/[\u0000-\u001f\u007f/\\:*?"<>|]/g, "")
    .trim()
    .replace(/^\.+/, "")
    .slice(0, MAX_FILE_NAME)
    .trim();
  return cleaned || "media";
}

/**
 * What the app itself observes when a request arrives: the view is shown, its own iframe holds
 * focus, and the app has transient user activation. This is the owner-accepted recent-activation
 * heuristic, not proof that one fresh click inside this frame asked for this effect: activation
 * lasts the browser's activation window and focus filters most, not all, foreign activation.
 * A boolean sent by the frame is never consulted. saveAs relies on the save dialog for intent.
 */
export interface ViewHostIntent {
  shown: boolean;
  frameFocused: boolean;
  activated: boolean;
}

export function intentGesture(intent: ViewHostIntent): boolean {
  return intent.shown && intent.frameFocused && intent.activated;
}

/** A rate limit, not a gesture detector: one request at a time per frame, at most one effect per interval. */
export const VIEW_HOST_COOLDOWN_MS = 1000;

export function createViewHostGate(now: () => number = () => Date.now()) {
  let busy = false;
  let quietUntil = 0;
  return {
    /** Claims the gate for one request; `false` when another is running or an effect just happened. */
    claim(): boolean {
      if (busy || now() < quietUntil) return false;
      busy = true;
      return true;
    },
    release(acted: boolean) {
      busy = false;
      if (acted) quietUntil = now() + VIEW_HOST_COOLDOWN_MS;
    },
  };
}

export type ViewHostGate = ReturnType<typeof createViewHostGate>;

/**
 * Performs one request. `isCurrent` is the app's fence for the asking frame: it is rechecked after
 * every await and before every effect (clipboard, dialog, daemon write, file manager, download), so
 * a frame closed, reloaded or replaced meanwhile gets `denied / stale` and nothing happens.
 */
export async function performViewHostAction(
  pluginId: string,
  frame: string | null,
  message: { action?: unknown; args?: unknown },
  intent: ViewHostIntent,
  deps: ViewHostDeps,
  isCurrent: () => boolean,
  gate: ViewHostGate,
): Promise<ViewHostResult> {
  const action = VIEW_HOST_ACTIONS.find((name) => name === message.action);
  if (!action) return refused("invalid", "action");
  if (!intentGesture(intent)) return refused("denied", "gesture");
  if (!gate.claim()) return refused("denied", "busy");
  let acted = false;
  const stale = refused("denied", "stale");
  const args = record(message.args) ?? {};
  try {
    if (action === "copyText") {
      const text = args.text;
      if (typeof text !== "string" || text.length > MAX_COPY_TEXT) return refused("invalid", "text");
      const writeText = deps.writeText;
      if (!writeText) return refused("unavailable", "clipboard");
      const declared = viewHostResult(await deps.call({ pluginId, action }));
      if (!declared.ok) return declared;
      if (!isCurrent()) return stale;
      acted = true;
      try {
        await writeText(text);
      } catch {
        return refused("unavailable", "clipboard");
      }
      return { ok: true };
    }
    const handle = args.handle;
    if (typeof handle !== "string" || !handle) return refused("invalid", "handle");
    const media = { pluginId, frame, handle };
    if (action === "reveal") {
      if (!deps.reveal) return refused("unavailable", "reveal");
      const located = viewHostResult(await deps.call({ ...media, action }));
      if (!located.ok) return located;
      if (!located.path) return refused("unavailable", "host");
      if (!isCurrent()) return stale;
      acted = true;
      try {
        await deps.reveal(located.path);
      } catch {
        return refused("unavailable", "reveal_failed");
      }
      return { ok: true };
    }
    const name = safeFileName(args.suggestedName);
    if (!deps.pickDestination) {
      acted = true;
      return await deps.download(media, name, isCurrent);
    }
    // Preflight without a destination: only `invalid / destination` means the dialog is worth showing.
    const preflight = viewHostResult(await deps.call({ ...media, action }));
    if (preflight.ok || preflight.code !== "invalid" || preflight.reason !== "destination") {
      return preflight.ok ? refused("unavailable", "host") : preflight;
    }
    if (!isCurrent()) return stale;
    acted = true;
    const destination = await deps.pickDestination(name);
    if (!destination) return refused("denied", "cancelled");
    if (!isCurrent()) return stale;
    const saved = viewHostResult(await deps.call({ ...media, action, destination }));
    return saved.ok ? { ok: true } : saved;
  } catch {
    return refused("unavailable", "host");
  } finally {
    gate.release(acted);
  }
}

import { baseDaemonTransport } from "./daemonBootstrap";
import { nativeBridge } from "./nativeBridge";
import { viewHostResult, type ViewHostDeps, type ViewHostMediaRequest, type ViewHostResult } from "./pluginViewHostActions";

// Plugin views load from this machine's daemon (`usePluginDocument`), so their host actions go
// there too, never through a selected mesh relay: the frame token and media belong to it.
const HOST_ACTION_PATH = "/api/plugins/view-host-action";

/** Streams the plugin's file from the daemon and hands it to the browser as a download, if the frame is still current. */
async function download(request: ViewHostMediaRequest, fileName: string, isCurrent: () => boolean): Promise<ViewHostResult> {
  const response = await baseDaemonTransport().request!(`${HOST_ACTION_PATH}/download`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(request),
  }, true);
  if (!response.ok) return viewHostResult(await response.json().catch(() => null));
  const blob = await response.blob();
  if (!isCurrent()) return { ok: false, code: "denied", reason: "stale" };
  const url = URL.createObjectURL(blob);
  try {
    const link = document.createElement("a");
    link.href = url;
    link.download = fileName;
    link.rel = "noopener";
    link.click();
  } finally {
    setTimeout(() => URL.revokeObjectURL(url), 60_000);
  }
  return { ok: true };
}

/** The native dialog and file manager exist only in the desktop app; the web mirror downloads and refuses reveal. */
export function viewHostDeps(): ViewHostDeps {
  const dialogs = nativeBridge.dialogs;
  const clipboard = globalThis.navigator?.clipboard;
  return {
    call: (request) => baseDaemonTransport().json("POST", HOST_ACTION_PATH, request),
    writeText: clipboard ? (text) => clipboard.writeText(text) : undefined,
    pickDestination: dialogs ? (defaultPath) => dialogs.save({ defaultPath }) : undefined,
    download,
    reveal: dialogs ? (path) => nativeBridge.revealFile(path) : undefined,
  };
}

use crate::service::MuxEmitCause;
use serde::Serialize;

use super::model::{
    choose_owner, owner_label, parse_surface_target, resolve_surface_decl, surface_placement,
    surface_renderable, surface_tab_row, DeclaredSurfaceRow, PluginSurfaceFacts, SurfaceError,
    SurfaceOpenRequest, SurfaceTabRow, SurfaceTarget,
};
use crate::multiplexer::state::MultiplexerState;
use crate::multiplexer::types::{SurfaceBacking, TabBacking};
use crate::service::team_membership::{
    apply_team_attachment_under, authorize_team_attachment, AttachmentParent,
};
use crate::service::ServiceContext;

#[derive(Debug, Clone, Serialize)]
pub struct SurfaceList {
    pub declared: Vec<DeclaredSurfaceRow>,
    pub open: Vec<SurfaceTabRow>,
}

#[derive(Debug, Clone, Serialize)]
pub struct SurfaceClosed {
    pub tab_id: String,
    pub warnings: Vec<String>,
}

impl ServiceContext {
    fn plugin_surface_facts(&self, plugin_id: &str) -> PluginSurfaceFacts {
        PluginSurfaceFacts {
            declared: self
                .ext::<codeterm_plugin::surfaces::SurfaceRegistryHandle>()
                .get(plugin_id)
                .map(|declared| declared.to_vec()),
            view_registered: self
                .ext::<crate::view_host::ViewRegistryHandle>()
                .get(plugin_id)
                .is_some(),
            runtimes: self
                .ext::<std::sync::Arc<crate::service::surface::SurfaceRuntimeRegistry>>()
                .runtime_names(),
        }
    }

    pub fn open_surface(&self, request: SurfaceOpenRequest) -> Result<SurfaceTabRow, SurfaceError> {
        let target = parse_surface_target(&request.target)?;
        let surface = resolve_surface_decl(&target, &self.plugin_surface_facts(&target.plugin_id))?;
        crate::service::tab::validate_tab_title(&surface.title).map_err(SurfaceError::Placement)?;
        let backing = SurfaceBacking {
            plugin_id: target.plugin_id.clone(),
            surface_id: target.surface_id.clone(),
            instance_id: uuid::Uuid::new_v4().simple().to_string(),
            owner_label: owner_label(&surface, request.title_from_owner),
            resume_url: None,
            resume_profile: None,
        };
        let gate = self.limit_gate();
        let row = {
            let mut mux = self.mux.write();
            crate::service::billing::admit_new_tab(&gate, &mux).map_err(SurfaceError::Placement)?;
            place_surface_tab(&mut mux, &request, &target, &surface.title, backing)?
        };
        self.emit_state_changed(MuxEmitCause::Surface);
        Ok(row)
    }

    pub fn list_surfaces(&self) -> SurfaceList {
        let mut declared = Vec::new();
        let runtimes = self
            .ext::<std::sync::Arc<crate::service::surface::SurfaceRuntimeRegistry>>()
            .runtime_names();
        for plugin_id in self
            .ext::<codeterm_plugin::surfaces::SurfaceRegistryHandle>()
            .ids()
        {
            let view_registered = self
                .ext::<crate::view_host::ViewRegistryHandle>()
                .get(&plugin_id)
                .is_some();
            let Some(surfaces) = self
                .ext::<codeterm_plugin::surfaces::SurfaceRegistryHandle>()
                .get(&plugin_id)
            else {
                continue;
            };
            declared.extend(
                surfaces
                    .iter()
                    .filter(|surface| surface_renderable(surface, view_registered, &runtimes))
                    .map(|surface| DeclaredSurfaceRow::new(&plugin_id, surface)),
            );
        }
        declared.sort_by(|a, b| (&a.plugin_id, &a.surface_id).cmp(&(&b.plugin_id, &b.surface_id)));
        let mux = self.mux.read();
        let mut open: Vec<SurfaceTabRow> = mux
            .all_tabs()
            .filter_map(|tab| surface_tab_row(tab, mux.find_workspace_for_tab(&tab.id)))
            .collect();
        drop(mux);
        open.sort_by(|a, b| a.tab_id.cmp(&b.tab_id));
        SurfaceList { declared, open }
    }

    pub fn close_surface(
        &self,
        caller_tab_id: Option<&str>,
        tab_id: &str,
    ) -> Result<SurfaceClosed, SurfaceError> {
        let resolved = {
            let mux = self.mux.read();
            let resolved = mux
                .resolve_tab_id(tab_id)
                .ok_or_else(|| SurfaceError::TabNotFound(tab_id.to_string()))?;
            let tab = mux
                .get_tab(&resolved)
                .ok_or_else(|| SurfaceError::TabNotFound(tab_id.to_string()))?;
            if tab.surface().is_none() {
                return Err(SurfaceError::NotASurface(resolved));
            }
            resolved
        };
        let warnings = self
            .close_tab_guarded(caller_tab_id, &resolved, false)
            .map_err(SurfaceError::Placement)?;
        Ok(SurfaceClosed {
            tab_id: resolved,
            warnings,
        })
    }
}

fn place_surface_tab(
    mux: &mut MultiplexerState,
    request: &SurfaceOpenRequest,
    target: &SurfaceTarget,
    title: &str,
    backing: SurfaceBacking,
) -> Result<SurfaceTabRow, SurfaceError> {
    let explicit_owner = match request.owner_tab_id.as_deref() {
        Some(raw) => Some(
            mux.resolve_tab_id(raw)
                .ok_or_else(|| SurfaceError::OwnerNotFound(raw.to_string()))?,
        ),
        None => None,
    };
    let caller = request
        .caller_tab_id
        .as_deref()
        .and_then(|raw| mux.resolve_tab_id(raw))
        .and_then(|id| mux.get_tab(&id));
    let owner_id = choose_owner(explicit_owner.as_deref(), caller).map(str::to_string);
    let owner = match owner_id.as_deref() {
        Some(id) => {
            let owner = mux
                .get_tab(id)
                .ok_or_else(|| SurfaceError::OwnerNotFound(id.to_string()))?;
            if owner.surface().is_some() {
                return Err(SurfaceError::OwnerIsSurface(id.to_string()));
            }
            Some(owner)
        }
        None => None,
    };
    let placement = surface_placement(owner);
    let owner_workspace = owner_id
        .as_deref()
        .and_then(|id| mux.find_workspace_for_tab(id));
    let workspace_id = match (request.workspace_id.clone(), owner_workspace) {
        (Some(requested), Some(owner_workspace)) if requested != owner_workspace => {
            return Err(SurfaceError::WorkspaceMismatch {
                requested,
                owner_workspace,
            });
        }
        (requested, owner_workspace) => crate::service::spawn::resolve_spawn_workspace_id(
            requested.or(owner_workspace),
            None,
            request.caller_tab_id.as_deref(),
            |tab| mux.find_workspace_for_tab(tab),
            mux.get_active_workspace()
                .map(|workspace| workspace.id.clone()),
            mux.list_workspaces()
                .first()
                .map(|workspace| workspace.id.clone()),
        )
        .map_err(SurfaceError::Placement)?,
    };
    let team_attachment = match (placement.team_id.as_deref(), owner_id.as_deref()) {
        (Some(team_id), Some(owner)) => Some(
            authorize_team_attachment(mux, team_id, owner, &workspace_id)
                .map_err(SurfaceError::Placement)?,
        ),
        _ => None,
    };
    let tab_id = mux
        .create_tab(&workspace_id)
        .map_err(SurfaceError::Placement)?;
    if let Err(error) = mux.rename_tab(&tab_id, title) {
        mux.rollback_spawn_tab(&workspace_id, &tab_id);
        return Err(SurfaceError::Placement(error));
    }
    let tab = mux
        .get_tab_mut(&tab_id)
        .ok_or_else(|| SurfaceError::Placement(format!("Tab {tab_id} vanished while opening")))?;
    tab.backing = TabBacking::Surface(backing);
    tab.parent_tab_id = placement.parent_tab_id;
    tab.spawned_by_tab_id = owner_id.clone();
    tab.depth = placement.depth;
    if let (Some(attachment), Some(owner)) = (team_attachment.as_ref(), owner_id.as_deref()) {
        let parent = AttachmentParent::Owner(owner);
        if let Err(error) = apply_team_attachment_under(mux, attachment, &tab_id, parent) {
            mux.rollback_spawn_tab(&workspace_id, &tab_id);
            return Err(SurfaceError::Placement(error));
        }
    }
    let tab = mux
        .get_tab(&tab_id)
        .ok_or_else(|| SurfaceError::Placement(format!("Tab {tab_id} vanished while opening")))?;
    let row = surface_tab_row(tab, Some(workspace_id)).ok_or_else(|| {
        SurfaceError::Placement(format!(
            "Tab {tab_id} lost its {}:{} backing",
            target.plugin_id, target.surface_id
        ))
    })?;
    Ok(row)
}

