//! `host.fetch` backend — an allowlisted HTTP request returning `{status, headers, body}`
//! (the caller enforces `network.allow` via `PluginSandbox::can_reach`). The sync VM
//! call runs the request on a dedicated OS thread, never a blocking client on a tokio worker.

use std::collections::HashMap;
use std::sync::LazyLock;
use std::time::Duration;

use codeterm_decision::physical;
use futures_util::StreamExt;
use parking_lot::Mutex;
use serde::Deserialize;

const MAX_STREAM_JOBS: usize = 128;
const MAX_STREAM_JOB_BUFFERED_BYTES: usize = 4 * 1024 * 1024;
const MAX_FETCH_BODY_BYTES: usize = 4 * 1024 * 1024;
const DEFAULT_FETCH_TIMEOUT_MS: u64 = 5_000;
const MAX_FETCH_TIMEOUT_MS: u64 = 30_000;
const FETCH_CLIENT_IDLE_TIMEOUT: Duration = Duration::from_secs(90);
const FETCH_CLIENT_TCP_KEEPALIVE: Duration = Duration::from_secs(60);

static FETCH_CLIENT: LazyLock<Result<reqwest::Client, String>> = LazyLock::new(build_fetch_client);
static DECISION_FETCH_CLIENT: LazyLock<Result<reqwest::Client, String>> = LazyLock::new(|| {
    fetch_client_builder()
        .retry(reqwest::retry::never())
        .build()
        .map_err(|_| "decision HTTP client unavailable".into())
});

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct FetchOpts {
    url: String,
    #[serde(default)]
    method: Option<String>,
    #[serde(default)]
    headers: HashMap<String, String>,
    #[serde(default)]
    body: Option<String>,
    #[serde(default)]
    timeout_ms: Option<u64>,
}

#[derive(Default)]
struct StreamJob {
    plugin_id: String,
    chunks: Vec<String>,
    buffered_bytes: usize,
    done: bool,
    status: Option<u16>,
    error: Option<String>,
}

static STREAM_JOBS: LazyLock<Mutex<HashMap<String, StreamJob>>> =
    LazyLock::new(|| Mutex::new(HashMap::new()));
#[cfg(test)]
static FETCH_CLIENT_BUILDS: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

fn err(msg: &str) -> String {
    serde_json::json!({ "error": msg }).to_string()
}

/// `host[:port]` of a URL, for the allowlist check. `None` if unparseable.
pub(super) fn host_of(opts_json: &str) -> Option<String> {
    let url = serde_json::from_str::<serde_json::Value>(opts_json)
        .ok()?
        .get("url")?
        .as_str()?
        .to_string();
    let rest = url.split("://").nth(1).unwrap_or(&url);
    rest.split('/').next().map(|s| s.to_string())
}

/// Perform the request described by `opts_json`. The host is already allowlisted.
///
/// Runs on a dedicated OS thread with its own current-thread runtime. The caller
/// blocks on `join`, which is fine because the VM call is synchronous anyway.
pub(super) fn run(opts_json: &str) -> String {
    let owned = opts_json.to_string();
    let observer = physical::current();
    match std::thread::spawn(move || {
        let _scope = observer.map(physical::RequestScope::enter);
        run_sync(&owned)
    })
    .join()
    {
        Ok(s) => s,
        Err(_) => err("fetch worker panicked"),
    }
}

pub(super) fn start(plugin_id: &str, opts_json: &str) -> String {
    if let Err(error) = serde_json::from_str::<FetchOpts>(opts_json) {
        return err(&format!("bad fetch opts: {error}"));
    }
    let owned = opts_json.to_string();
    let observer = physical::current();
    match super::host_exec::start_json_job(plugin_id, move || {
        let _scope = observer.map(physical::RequestScope::enter);
        run_sync(&owned)
    }) {
        Ok(job_id) => serde_json::json!({ "jobId": job_id }).to_string(),
        Err(error) => err(&error),
    }
}

/// Start an HTTP stream. The caller must run the same allowlist gate as `run`.
pub(super) fn stream(plugin_id: &str, opts_json: &str) -> String {
    if let Err(e) = serde_json::from_str::<FetchOpts>(opts_json) {
        return err(&format!("bad fetch opts: {e}"));
    }

    let job_id = match start_stream_job(plugin_id) {
        Ok(job_id) => job_id,
        Err(e) => return err(&e),
    };

    let owned = opts_json.to_string();
    let worker_job_id = job_id.clone();
    let observer = physical::current();
    std::thread::spawn(move || {
        let _scope = observer.map(physical::RequestScope::enter);
        run_stream_worker(worker_job_id, owned)
    });

    serde_json::json!({ "jobId": job_id }).to_string()
}

pub(super) fn stream_poll(plugin_id: &str, job_id: &str) -> String {
    let response = {
        let plugin_id = normalize_plugin_id(plugin_id);
        let mut jobs = STREAM_JOBS.lock();
        let Some(job) = jobs
            .get_mut(job_id)
            .filter(|job| job.plugin_id == plugin_id)
        else {
            return serde_json::json!({
                "chunks": [],
                "done": true,
                "error": "job not found",
            })
            .to_string();
        };

        let chunks = std::mem::take(&mut job.chunks);
        job.buffered_bytes = 0;
        let response = StreamPollResponse {
            chunks,
            done: job.done,
            status: job.status,
            error: job.error.clone(),
        };
        if job.done {
            jobs.remove(job_id);
        }
        response
    };

    let mut out = serde_json::Map::new();
    out.insert("chunks".to_string(), serde_json::json!(response.chunks));
    out.insert("done".to_string(), serde_json::json!(response.done));
    if let Some(status) = response.status {
        out.insert("status".to_string(), serde_json::json!(status));
    }
    if let Some(error) = response.error {
        out.insert("error".to_string(), serde_json::json!(error));
    }
    serde_json::Value::Object(out).to_string()
}

pub(super) fn stream_close(plugin_id: &str, job_id: &str) {
    let plugin_id = normalize_plugin_id(plugin_id);
    STREAM_JOBS
        .lock()
        .retain(|id, job| id != job_id || job.plugin_id != plugin_id);
}

pub(super) fn drop_plugin_jobs(plugin_id: &str) {
    let plugin_id = normalize_plugin_id(plugin_id);
    STREAM_JOBS
        .lock()
        .retain(|_, job| job.plugin_id != plugin_id);
}

fn build_fetch_client() -> Result<reqwest::Client, String> {
    #[cfg(test)]
    FETCH_CLIENT_BUILDS.fetch_add(1, std::sync::atomic::Ordering::SeqCst);

    fetch_client_builder()
        .build()
        .map_err(|e| format!("client: {e}"))
}

fn fetch_client_builder() -> reqwest::ClientBuilder {
    reqwest::Client::builder()
        .redirect(reqwest::redirect::Policy::none())
        .pool_idle_timeout(FETCH_CLIENT_IDLE_TIMEOUT)
        .tcp_keepalive(Some(FETCH_CLIENT_TCP_KEEPALIVE))
}

fn fetch_client() -> Result<&'static reqwest::Client, String> {
    if physical::current().is_some() {
        DECISION_FETCH_CLIENT.as_ref()
    } else {
        FETCH_CLIENT.as_ref()
    }
    .map_err(Clone::clone)
}

fn request_build_error(error: reqwest::Error) -> String {
    if physical::current().is_some() {
        "invalid fetch request".into()
    } else {
        format!("request failed: {error}")
    }
}

fn transport_error(stage: &str, error: reqwest::Error) -> String {
    if physical::current().is_some() {
        stage.into()
    } else {
        format!("{stage}: {error}")
    }
}

fn fetch_timeout(opts: &FetchOpts) -> Duration {
    Duration::from_millis(
        opts.timeout_ms
            .unwrap_or(DEFAULT_FETCH_TIMEOUT_MS)
            .clamp(1, MAX_FETCH_TIMEOUT_MS),
    )
}

fn request_builder(client: &reqwest::Client, opts: &FetchOpts) -> reqwest::RequestBuilder {
    let timeout = physical::deadline().map_or_else(
        || fetch_timeout(opts),
        |deadline| {
            fetch_timeout(opts).min(deadline.saturating_duration_since(std::time::Instant::now()))
        },
    );
    let method = reqwest::Method::from_bytes(
        opts.method
            .as_deref()
            .unwrap_or("GET")
            .to_uppercase()
            .as_bytes(),
    )
    .unwrap_or(reqwest::Method::GET);
    let mut req = client.request(method, &opts.url).timeout(timeout);
    for (k, v) in &opts.headers {
        req = req.header(k, v);
    }
    if let Some(b) = &opts.body {
        req = req.body(b.clone());
    }
    req
}

fn run_sync(opts_json: &str) -> String {
    let result = std::panic::catch_unwind(|| {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .map_err(|e| format!("fetch runtime: {e}"))?;
        runtime.block_on(run_async(opts_json))
    });

    match result {
        Ok(Ok(s)) => s,
        Ok(Err(e)) => err(&e),
        Err(_) => err("fetch worker panicked"),
    }
}

async fn run_async(opts_json: &str) -> Result<String, String> {
    let opts: FetchOpts = match serde_json::from_str(opts_json) {
        Ok(o) => o,
        Err(e) => return Ok(err(&format!("bad fetch opts: {e}"))),
    };
    let req = request_builder(fetch_client()?, &opts)
        .build()
        .map_err(request_build_error)?;
    physical::before_request().map_err(|_| "decision request refused".to_string())?;
    match fetch_client()?.execute(req).await {
        Ok(resp) => {
            let status = resp.status().as_u16();
            let headers: HashMap<String, String> = resp
                .headers()
                .iter()
                .map(|(k, v)| (k.to_string(), v.to_str().unwrap_or("").to_string()))
                .collect();
            let mut body = Vec::new();
            let mut stream = resp.bytes_stream();
            while let Some(chunk) = stream.next().await {
                let chunk = match chunk {
                    Ok(chunk) => chunk,
                    Err(error) => return Ok(err(&transport_error("response read failed", error))),
                };
                if body.len().saturating_add(chunk.len()) > MAX_FETCH_BODY_BYTES {
                    return Ok(err("fetch response exceeds the 4 MiB limit"));
                }
                body.extend_from_slice(&chunk);
            }
            let body = String::from_utf8_lossy(&body).into_owned();
            Ok(
                serde_json::json!({ "status": status, "headers": headers, "body": body })
                    .to_string(),
            )
        }
        Err(e) => Ok(err(&transport_error("request failed", e))),
    }
}

fn run_stream_worker(job_id: String, opts_json: String) {
    let result = std::panic::catch_unwind(|| {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .map_err(|e| format!("stream runtime: {e}"))?;
        runtime.block_on(run_stream_async(job_id.clone(), opts_json))
    });

    let error = match result {
        Ok(Ok(())) => None,
        Ok(Err(e)) => Some(e),
        Err(_) => Some("fetch stream worker panicked".to_string()),
    };
    if let Some(error) = error {
        finish_stream_job(&job_id, Some(error));
    }
}

async fn run_stream_async(job_id: String, opts_json: String) -> Result<(), String> {
    let opts: FetchOpts =
        serde_json::from_str(&opts_json).map_err(|e| format!("bad fetch opts: {e}"))?;
    let req = request_builder(fetch_client()?, &opts)
        .build()
        .map_err(request_build_error)?;
    physical::before_request().map_err(|_| "decision request refused".to_string())?;

    let resp = fetch_client()?
        .execute(req)
        .await
        .map_err(|e| transport_error("request failed", e))?;
    set_stream_status(&job_id, resp.status().as_u16());

    let mut stream = resp.bytes_stream();
    let mut pending_utf8 = Vec::new();
    while let Some(next) = stream.next().await {
        match next {
            Ok(bytes) => {
                if let Some(chunk) = decode_utf8_prefix(&mut pending_utf8, &bytes) {
                    if !push_stream_chunk(&job_id, chunk) {
                        return Ok(());
                    }
                }
            }
            Err(e) => return Err(transport_error("stream failed", e)),
        }
    }
    if let Some(chunk) = flush_utf8_remainder(&mut pending_utf8) {
        if !push_stream_chunk(&job_id, chunk) {
            return Ok(());
        }
    }
    finish_stream_job(&job_id, None);
    Ok(())
}

struct StreamPollResponse {
    chunks: Vec<String>,
    done: bool,
    status: Option<u16>,
    error: Option<String>,
}

fn normalize_plugin_id(plugin_id: &str) -> String {
    if plugin_id.is_empty() {
        "anonymous".to_string()
    } else {
        plugin_id.to_string()
    }
}

fn start_stream_job(plugin_id: &str) -> Result<String, String> {
    let plugin_id = normalize_plugin_id(plugin_id);
    let mut jobs = STREAM_JOBS.lock();
    jobs.retain(|_, job| !job.done || !job.chunks.is_empty());
    if jobs.len() >= MAX_STREAM_JOBS {
        return Err("too many fetch stream jobs".to_string());
    }

    let job_id = format!("fetch:{plugin_id}:{}", uuid::Uuid::new_v4().simple());
    jobs.insert(
        job_id.clone(),
        StreamJob {
            plugin_id,
            ..StreamJob::default()
        },
    );
    Ok(job_id)
}

fn decode_utf8_prefix(pending: &mut Vec<u8>, frame: &[u8]) -> Option<String> {
    pending.extend_from_slice(frame);
    match std::str::from_utf8(pending) {
        Ok(valid) => {
            let out = valid.to_string();
            pending.clear();
            (!out.is_empty()).then_some(out)
        }
        Err(e) if e.error_len().is_none() => {
            let valid_up_to = e.valid_up_to();
            if valid_up_to == 0 {
                return None;
            }
            let out = std::str::from_utf8(&pending[..valid_up_to])
                .unwrap_or_default()
                .to_string();
            let tail = pending[valid_up_to..].to_vec();
            *pending = tail;
            Some(out)
        }
        Err(_) => {
            let out = String::from_utf8_lossy(pending).to_string();
            pending.clear();
            (!out.is_empty()).then_some(out)
        }
    }
}

fn flush_utf8_remainder(pending: &mut Vec<u8>) -> Option<String> {
    if pending.is_empty() {
        None
    } else {
        let out = String::from_utf8_lossy(pending).to_string();
        pending.clear();
        Some(out)
    }
}

fn set_stream_status(job_id: &str, status: u16) {
    if let Some(job) = STREAM_JOBS.lock().get_mut(job_id) {
        job.status = Some(status);
    }
}

fn push_stream_chunk(job_id: &str, chunk: String) -> bool {
    if let Some(job) = STREAM_JOBS.lock().get_mut(job_id) {
        if job.done {
            return false;
        }
        let chunk_bytes = chunk.len();
        if job.buffered_bytes.saturating_add(chunk_bytes) > MAX_STREAM_JOB_BUFFERED_BYTES {
            job.done = true;
            job.error = Some("fetch stream buffer limit exceeded".to_string());
            return false;
        }
        job.buffered_bytes += chunk_bytes;
        job.chunks.push(chunk);
        true
    } else {
        false
    }
}

fn finish_stream_job(job_id: &str, error: Option<String>) {
    if let Some(job) = STREAM_JOBS.lock().get_mut(job_id) {
        job.done = true;
        job.error = error;
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::js_runtime::host_api::PluginSandbox;
    use std::io::Write;
    use std::net::TcpListener;
    use std::sync::atomic::Ordering;
    use std::sync::mpsc;
    use std::thread;
    use std::time::Instant;

    static TEST_LOCK: LazyLock<Mutex<()>> = LazyLock::new(|| Mutex::new(()));

    #[test]
    fn fetch_timeout_is_bounded() {
        let opts = FetchOpts {
            url: "http://localhost".into(),
            method: None,
            headers: HashMap::new(),
            body: None,
            timeout_ms: Some(u64::MAX),
        };
        assert_eq!(
            fetch_timeout(&opts),
            Duration::from_millis(MAX_FETCH_TIMEOUT_MS)
        );
    }

    fn serve_chunked(chunks: Vec<&'static str>) -> String {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let mut request = [0_u8; 1024];
            let _ = std::io::Read::read(&mut stream, &mut request);
            write!(
                stream,
                "HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\nContent-Type: text/plain\r\n\r\n"
            )
            .unwrap();
            for chunk in chunks {
                write!(stream, "{:x}\r\n{}\r\n", chunk.len(), chunk).unwrap();
                stream.flush().unwrap();
                thread::sleep(Duration::from_millis(10));
            }
            write!(stream, "0\r\n\r\n").unwrap();
        });
        format!("http://{addr}/stream")
    }

    fn serve_fixed(body: &'static str, requests: usize) -> String {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        thread::spawn(move || {
            for _ in 0..requests {
                let (mut stream, _) = listener.accept().unwrap();
                let mut request = [0_u8; 1024];
                let _ = std::io::Read::read(&mut stream, &mut request);
                write!(
                    stream,
                    "HTTP/1.1 200 OK\r\nContent-Length: {}\r\n\r\n{}",
                    body.len(),
                    body
                )
                .unwrap();
            }
        });
        format!("http://{addr}/ok")
    }

    fn serve_unresponsive() -> String {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            let mut request = [0_u8; 1024];
            let _ = std::io::Read::read(&mut stream, &mut request);
            thread::sleep(Duration::from_secs(10));
        });
        format!("http://{addr}/slow")
    }

    fn poll_until_done(plugin_id: &str, job_id: &str) -> serde_json::Value {
        let started = Instant::now();
        let mut all_chunks = Vec::new();
        loop {
            let poll: serde_json::Value =
                serde_json::from_str(&stream_poll(plugin_id, job_id)).unwrap();
            if let Some(chunks) = poll["chunks"].as_array() {
                all_chunks.extend(chunks.iter().filter_map(|c| c.as_str()).map(str::to_string));
            }
            if poll["done"].as_bool() == Some(true) {
                return serde_json::json!({
                    "chunks": all_chunks,
                    "done": true,
                    "status": poll["status"],
                    "error": poll["error"],
                });
            }
            assert!(
                started.elapsed() < Duration::from_secs(5),
                "stream timed out"
            );
            thread::sleep(Duration::from_millis(10));
        }
    }

    fn reset_stream_jobs() {
        STREAM_JOBS.lock().clear();
    }

    fn serve_redirect_pair() -> (String, mpsc::Receiver<()>) {
        let target = TcpListener::bind("127.0.0.1:0").unwrap();
        let target_addr = target.local_addr().unwrap();
        let redirect = TcpListener::bind("127.0.0.1:0").unwrap();
        let redirect_addr = redirect.local_addr().unwrap();
        let (tx, rx) = mpsc::channel();

        thread::spawn(move || {
            if let Ok((mut stream, _)) = target.accept() {
                let _ = tx.send(());
                let _ = write!(
                    stream,
                    "HTTP/1.1 200 OK\r\nContent-Length: 7\r\n\r\nescaped"
                );
            }
        });
        thread::spawn(move || {
            let (mut stream, _) = redirect.accept().unwrap();
            let mut request = [0_u8; 1024];
            let _ = std::io::Read::read(&mut stream, &mut request);
            write!(
                stream,
                "HTTP/1.1 302 Found\r\nLocation: http://{target_addr}/escaped\r\nContent-Length: 0\r\n\r\n"
            )
            .unwrap();
        });

        (format!("http://{redirect_addr}/start"), rx)
    }

    #[test]
    fn stream_returns_job_id_and_poll_drains_chunks_until_done() {
        let _guard = TEST_LOCK.lock();
        reset_stream_jobs();
        let url = serve_chunked(vec!["hello ", "stream"]);
        let started: serde_json::Value = serde_json::from_str(&stream(
            "test-plugin",
            &serde_json::json!({ "url": url }).to_string(),
        ))
        .unwrap();
        let job_id = started["jobId"].as_str().expect("job id");
        assert!(job_id.starts_with("fetch:test-plugin:"));

        let done = poll_until_done("test-plugin", job_id);
        assert_eq!(done["chunks"], serde_json::json!(["hello ", "stream"]));
        assert_eq!(done["done"], true);
        assert_eq!(done["status"], 200);

        let missing: serde_json::Value =
            serde_json::from_str(&stream_poll("test-plugin", job_id)).unwrap();
        assert_eq!(missing["error"], "job not found");
    }

    #[test]
    fn stream_uses_the_same_allowlist_gate_as_fetch() {
        let _guard = TEST_LOCK.lock();
        reset_stream_jobs();
        let sb = PluginSandbox::restricted(vec![], vec![]);
        let opts = serde_json::json!({ "url": "http://blocked.example.test/stream" }).to_string();
        let host = host_of(&opts).unwrap_or_default();

        let raw = if sb.can_reach(&host) {
            stream("test-plugin", &opts)
        } else {
            err(&format!("fetch denied: {host}"))
        };

        let denied: serde_json::Value = serde_json::from_str(&raw).unwrap();
        assert_eq!(denied["error"], "fetch denied: blocked.example.test");
    }

    #[test]
    fn utf8_decoder_carries_multibyte_boundaries_without_replacement_chars() {
        let _guard = TEST_LOCK.lock();
        let frames = [vec![0xd0], vec![0x96, 0xf0], vec![0x9f, 0x99], vec![0x82]];
        let mut pending = Vec::new();
        let mut out = String::new();

        for frame in frames {
            if let Some(chunk) = decode_utf8_prefix(&mut pending, &frame) {
                out.push_str(&chunk);
            }
        }
        if let Some(chunk) = flush_utf8_remainder(&mut pending) {
            out.push_str(&chunk);
        }

        assert_eq!(out, "Ж🙂");
        assert!(!out.contains('\u{fffd}'));
    }

    #[test]
    fn stream_job_count_is_capped() {
        let _guard = TEST_LOCK.lock();
        reset_stream_jobs();
        for _ in 0..MAX_STREAM_JOBS {
            start_stream_job("cap-plugin").unwrap();
        }

        assert_eq!(
            start_stream_job("cap-plugin").unwrap_err(),
            "too many fetch stream jobs"
        );
        drop_plugin_jobs("cap-plugin");
    }

    #[test]
    fn stream_job_buffer_is_capped() {
        let _guard = TEST_LOCK.lock();
        reset_stream_jobs();
        let job_id = start_stream_job("cap-plugin").unwrap();
        assert!(!push_stream_chunk(
            &job_id,
            "x".repeat(MAX_STREAM_JOB_BUFFERED_BYTES + 1)
        ));

        let poll: serde_json::Value =
            serde_json::from_str(&stream_poll("cap-plugin", &job_id)).unwrap();
        assert_eq!(poll["done"], true);
        assert_eq!(poll["error"], "fetch stream buffer limit exceeded");
    }

    #[test]
    fn blocking_fetch_does_not_follow_redirects_outside_allowlist() {
        let _guard = TEST_LOCK.lock();
        let (url, escaped_rx) = serve_redirect_pair();
        let body: serde_json::Value =
            serde_json::from_str(&run(&serde_json::json!({ "url": url }).to_string())).unwrap();

        assert_eq!(body["status"], 302);
        assert!(escaped_rx.recv_timeout(Duration::from_millis(100)).is_err());
    }

    #[test]
    fn fetch_reuses_shared_client_across_calls() {
        let _guard = TEST_LOCK.lock();
        let before = FETCH_CLIENT_BUILDS.load(Ordering::SeqCst);
        let first = fetch_client().unwrap() as *const reqwest::Client;
        let second = fetch_client().unwrap() as *const reqwest::Client;
        assert_eq!(first, second);
        let after_lookup = FETCH_CLIENT_BUILDS.load(Ordering::SeqCst);
        assert_eq!(after_lookup, before + usize::from(before == 0));

        let url = serve_fixed("ok", 2);
        for _ in 0..2 {
            let body: serde_json::Value =
                serde_json::from_str(&run(&serde_json::json!({ "url": url }).to_string())).unwrap();
            assert_eq!(body["status"], 200);
            assert_eq!(body["body"], "ok");
        }
        assert_eq!(FETCH_CLIENT_BUILDS.load(Ordering::SeqCst), after_lookup);
    }

    #[test]
    fn fetch_defaults_to_five_seconds_and_its_timeout_fails_the_request() {
        let _guard = TEST_LOCK.lock();
        let url = serve_unresponsive();
        // The default is checked on the built request, so the test never waits it out.
        let unset: FetchOpts =
            serde_json::from_str(&serde_json::json!({ "url": url }).to_string()).unwrap();
        let request = request_builder(fetch_client().unwrap(), &unset)
            .build()
            .unwrap();
        assert_eq!(
            request.timeout(),
            Some(&Duration::from_millis(DEFAULT_FETCH_TIMEOUT_MS))
        );

        let body: serde_json::Value = serde_json::from_str(&run(
            &serde_json::json!({ "url": url, "timeoutMs": 50 }).to_string(),
        ))
        .unwrap();
        assert!(
            body["error"]
                .as_str()
                .unwrap_or_default()
                .contains("request failed"),
            "unexpected response: {body}"
        );
    }

    #[test]
    fn stream_fetch_does_not_follow_redirects_outside_allowlist() {
        let _guard = TEST_LOCK.lock();
        reset_stream_jobs();
        let (url, escaped_rx) = serve_redirect_pair();
        let started: serde_json::Value = serde_json::from_str(&stream(
            "redirect-plugin",
            &serde_json::json!({ "url": url }).to_string(),
        ))
        .unwrap();
        let job_id = started["jobId"].as_str().expect("job id");

        let done = poll_until_done("redirect-plugin", job_id);
        assert_eq!(done["status"], 302);
        assert!(escaped_rx.recv_timeout(Duration::from_millis(100)).is_err());
    }
}

#[cfg(test)]
mod physical_tests {
    use super::*;
    use codeterm_decision::{physical, DecisionError};
    use std::sync::{
        atomic::{AtomicUsize, Ordering},
        Arc,
    };

    struct Meter(AtomicUsize);
    impl physical::RequestObserver for Meter {
        fn before_request(&self) -> Result<(), DecisionError> {
            self.0.fetch_add(1, Ordering::SeqCst);
            Ok(())
        }
    }

    #[test]
    fn decision_physical_scope_keeps_default_fetch_client_unchanged() {
        let default = fetch_client().unwrap() as *const reqwest::Client;
        let scope = physical::RequestScope::enter(Arc::new(Meter(AtomicUsize::new(0))));
        let decision = fetch_client().unwrap() as *const reqwest::Client;
        let error = fetch_client()
            .unwrap()
            .get("http://[invalid?token=opaque-secret")
            .build()
            .unwrap_err();
        assert_eq!(transport_error("request failed", error), "request failed");
        assert_ne!(decision, default);
        assert_eq!(fetch_client().unwrap() as *const reqwest::Client, decision);
        drop(scope);
        assert_eq!(fetch_client().unwrap() as *const reqwest::Client, default);
    }

    #[test]
    fn decision_physical_async_fetch_propagates_scope_and_deadline() {
        let _guard = crate::js_runtime::PROCESS_TEST_LOCK.lock();
        struct BoundedMeter {
            calls: AtomicUsize,
            deadline: std::time::Instant,
        }
        impl physical::RequestObserver for BoundedMeter {
            fn before_request(&self) -> Result<(), DecisionError> {
                self.calls.fetch_add(1, Ordering::SeqCst);
                Ok(())
            }
            fn deadline(&self) -> Option<std::time::Instant> {
                Some(self.deadline)
            }
        }
        let meter = Arc::new(BoundedMeter {
            calls: AtomicUsize::new(0),
            deadline: std::time::Instant::now() + Duration::from_secs(2),
        });
        let scope = physical::RequestScope::enter(meter.clone());
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let url = format!("http://{}/", listener.local_addr().unwrap());
        let server = std::thread::spawn(move || {
            use std::io::{Read, Write};
            let (mut stream, _) = listener.accept().unwrap();
            stream
                .set_read_timeout(Some(Duration::from_secs(2)))
                .unwrap();
            let mut bytes = [0; 2048];
            assert!(stream.read(&mut bytes).unwrap() > 0);
            stream
                .write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nok")
                .unwrap();
        });
        let opts = serde_json::json!({"url": url, "timeoutMs": 30000}).to_string();
        let request = request_builder(
            fetch_client().unwrap(),
            &serde_json::from_str(&opts).unwrap(),
        )
        .build()
        .unwrap();
        assert!(request.timeout().unwrap() <= &Duration::from_secs(2));
        let started: serde_json::Value =
            serde_json::from_str(&start("physical-async", &opts)).unwrap();
        drop(scope);
        let super::super::host_exec::WaitResult::Completed(done) =
            super::super::host_exec::wait_json(
                "physical-async",
                started["jobId"].as_str().unwrap(),
            )
        else {
            panic!("fetch event did not complete before its failure deadline");
        };
        let done: serde_json::Value = serde_json::from_str(&done).unwrap();
        server.join().unwrap();
        assert!(done.get("error").is_none(), "fetch completion: {done}");
        assert_eq!(done["status"], 200);
        assert_eq!(done["body"], "ok");
        assert_eq!(meter.calls.load(Ordering::SeqCst), 1);
        assert!(physical::current().is_none());
    }

    #[test]
    fn decision_physical_fetch_workers_propagate_call_scope() {
        let meter = Arc::new(Meter(AtomicUsize::new(0)));
        let scope = physical::RequestScope::enter(meter.clone());
        let malformed: serde_json::Value = serde_json::from_str(&run("{}")).unwrap();
        assert!(malformed["error"].is_string());
        assert_eq!(meter.0.load(Ordering::SeqCst), 0);
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let url = format!("http://{}/", listener.local_addr().unwrap());
        let serve = std::thread::spawn(move || {
            use std::io::{Read, Write};
            let (mut stream, _) = listener.accept().unwrap();
            let mut buf = [0; 2048];
            assert!(stream.read(&mut buf).unwrap() > 0);
            stream
                .write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nok")
                .unwrap();
        });
        let opts = serde_json::json!({"url": url}).to_string();
        let result: serde_json::Value = serde_json::from_str(&run(&opts)).unwrap();
        assert_eq!(result["status"], 200);
        serve.join().unwrap();
        assert_eq!(meter.0.load(Ordering::SeqCst), 1);
        drop(scope);
        assert!(physical::current().is_none());
    }
}

//! `JsTranscriber` — adapts a JS plugin that declares `capabilities.transcriber`
//! to the core [`Transcriber`](crate::transcribe::Transcriber) trait. Mirrors
//! `JsProvider`: it wraps the shared `Arc<PluginVm>` and dispatches to exported
//! plugin functions via the synchronous `call_json` (the VM is not `Send`, so we
//! call it directly on the caller's thread — gap G1).

use std::path::Path;
use std::sync::Arc;

use async_trait::async_trait;
use serde::Deserialize;
use serde_json::json;

use super::vm::{call_json, PluginVm};
use crate::transcribe::{TranscribeError, Transcriber, TranscriberStatus, Transcript};

pub struct JsTranscriber {
    vm: Arc<PluginVm>,
    id: String,
}

impl JsTranscriber {
    pub fn new(vm: Arc<PluginVm>, id: impl Into<String>) -> Self {
        Self { vm, id: id.into() }
    }
}

#[derive(Deserialize)]
struct TranscribeOut {
    #[serde(default)]
    text: Option<String>,
    #[serde(default)]
    error: Option<String>,
}

#[derive(Deserialize)]
struct StatusOut {
    #[serde(default)]
    state: Option<String>,
    #[serde(default)]
    reason: Option<String>,
}

#[async_trait]
impl Transcriber for JsTranscriber {
    fn id(&self) -> &str {
        &self.id
    }

    async fn status(&self) -> TranscriberStatus {
        // `transcribeStatus` is optional; absent/error ⇒ assume Ready.
        match call_json::<StatusOut>(&self.vm, "transcribeStatus", &[]) {
            Ok(s) => match s.state.as_deref() {
                Some("loading") => TranscriberStatus::Loading,
                Some("unloaded") => TranscriberStatus::Unloaded,
                Some("unavailable") => TranscriberStatus::Unavailable {
                    reason: s.reason.unwrap_or_default(),
                },
                _ => TranscriberStatus::Ready,
            },
            Err(_) => TranscriberStatus::Ready,
        }
    }

    async fn transcribe(
        &self,
        audio_path: &Path,
        language: &str,
    ) -> Result<Transcript, TranscribeError> {
        let args = [
            json!(audio_path.to_string_lossy().to_string()),
            json!(language),
        ];
        match call_json::<TranscribeOut>(&self.vm, "transcribe", &args) {
            Ok(out) => {
                if let Some(e) = out.error {
                    return Err(TranscribeError::RequestFailed(e));
                }
                let text = out.text.unwrap_or_default().trim().to_string();
                if text.is_empty() {
                    Err(TranscribeError::Empty)
                } else {
                    Ok(Transcript { text })
                }
            }
            Err(e) => Err(TranscribeError::RequestFailed(format!(
                "plugin transcribe failed: {e:?}"
            ))),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn vm_with(src: &str) -> Arc<PluginVm> {
        Arc::new(PluginVm::from_source("test-transcriber", src.to_string()).expect("vm"))
    }

    #[tokio::test]
    async fn transcribe_returns_text() {
        let vm = vm_with(
            r#"module.exports.default = {
                transcribe(path, lang) { return { text: "hello " + lang }; }
            }"#,
        );
        let t = JsTranscriber::new(vm, "test");
        let out = t.transcribe(Path::new("/a.oga"), "ru").await.unwrap();
        assert_eq!(out.text, "hello ru");
    }

    #[tokio::test]
    async fn empty_text_is_error() {
        let vm = vm_with(r#"module.exports.default = { transcribe() { return { text: "  " }; } }"#);
        let t = JsTranscriber::new(vm, "test");
        assert!(matches!(
            t.transcribe(Path::new("/a.oga"), "").await,
            Err(TranscribeError::Empty)
        ));
    }

    #[tokio::test]
    async fn plugin_error_propagates() {
        let vm = vm_with(
            r#"module.exports.default = { transcribe() { return { error: "engine down" }; } }"#,
        );
        let t = JsTranscriber::new(vm, "test");
        assert!(matches!(
            t.transcribe(Path::new("/a.oga"), "").await,
            Err(TranscribeError::RequestFailed(_))
        ));
    }

    // --- Real shipped plugin: load it, prove capabilities + the host.fetch path ---

    fn transcriber_manifest() -> std::path::PathBuf {
        crate::test_support::fixture_manifest_dir()
            .join("..")
            .join("plugins/transcriber/plugin.json")
    }

    #[test]
    fn shipped_transcriber_manifest_declares_capability() {
        let mp = transcriber_manifest();
        if !mp.exists() {
            return; // plugins/ not present in this checkout
        }
        let p = super::super::loader::load_one(&mp).expect("load transcriber");
        assert_eq!(p.manifest().id, "transcriber");
        assert!(p.manifest().capabilities.transcriber);
        assert!(
            !p.manifest().capabilities.agent_provider,
            "transcriber-only"
        );
        assert_eq!(p.manifest().host_api, Some(2));
    }

    // Multi-thread: the plugin's host.fetch blocks a worker on its request thread;
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn shipped_transcriber_transcribes_via_fake_daemon() {
        use axum::{routing::post, Json, Router};
        let mp = transcriber_manifest();
        if !mp.exists() {
            return;
        }
        // Fake transcribe daemon.
        let router = Router::new().route(
            "/transcribe",
            post(|| async { Json(serde_json::json!({ "text": "salut le monde" })) }),
        );
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr = listener.local_addr().unwrap();
        let (tx, rx) = tokio::sync::oneshot::channel::<()>();
        let handle = tokio::spawn(async move {
            let _ = axum::serve(listener, router)
                .with_graceful_shutdown(async move {
                    let _ = rx.await;
                })
                .await;
        });
        let p = super::super::loader::load_one(&mp).expect("load transcriber");
        let t = JsTranscriber::new(p.vm().clone(), p.manifest().id.clone());
        let out = {
            let mut env = codeterm_util::test_env::EnvGuard::lock();
            env.set("CODETERM_TRANSCRIBE_URL", format!("http://{addr}"));
            futures_executor::block_on(t.transcribe(Path::new("/note.oga"), "fr"))
        };

        let _ = tx.send(());
        let _ = handle.await;

        assert!(
            matches!(&out, Ok(t) if t.text == "salut le monde"),
            "got {out:?}"
        );
    }
}

//! `graphNodes` — a plugin's graph node declarations: media conversions the
//! host chains by declared capability, and typed, bounded event sources.
//!
//! Parsing is strict and closed: no bool form, no raw schema `Value`s, and none
//! of the open JSON Schema surface (`$ref`, combinators, nested objects).
//! Errors are field-named so a manifest typo names the exact key.

use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};

use crate::converter::Conversion;
use codeterm_blueprint_types::sentinel_input::MediaKind;

pub const MAX_CONVERTERS: usize = 16;
pub const MAX_EVENT_SOURCES: usize = 16;
pub const MAX_SCHEMA_PROPERTIES: usize = 32;
pub const MAX_STRING_LENGTH: u32 = 65536;
pub const MAX_ARRAY_ITEMS: u32 = 256;

const ROOT: &str = "capabilities.graphNodes";

/// `capabilities.graphNodes` — converters and event sources, both optional
/// lists; a present block must declare at least one node.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct GraphNodesCap {
    pub converters: Vec<Conversion>,
    pub event_sources: Vec<EventSourceDecl>,
}

impl GraphNodesCap {
    pub fn is_empty(&self) -> bool {
        self.converters.is_empty() && self.event_sources.is_empty()
    }

    pub fn enabled(&self) -> bool {
        !self.is_empty()
    }
}

/// One declared event source: a stable `kind`, a user-facing `title`, and the
/// typed schemas its params and event payload must satisfy.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EventSourceDecl {
    pub kind: String,
    pub title: String,
    pub params: Option<NodeSchema>,
    pub payload: Option<NodeSchema>,
}

/// A closed, bounded schema: an object of scalar or one-level scalar-array
/// properties.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NodeSchema {
    pub properties: Vec<NodeProperty>,
    pub required: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NodeProperty {
    pub name: String,
    pub schema: NodePropertySchema,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum NodePropertySchema {
    Scalar(NodeScalarSchema),
    Array {
        description: Option<String>,
        items: Box<NodeScalarSchema>,
        max_items: u32,
    },
}

/// A scalar type with its bounds: `enum` and `maxLength` for strings only.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NodeScalarSchema {
    pub description: Option<String>,
    pub kind: NodeScalarType,
    pub enum_values: Option<Vec<String>>,
    pub max_length: Option<u32>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NodeScalarType {
    String,
    Integer,
    Number,
    Boolean,
}

/// A failed instance check, pointing at the offending path (`$.text`).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SchemaError {
    pub path: String,
    pub message: String,
}

impl SchemaError {
    pub fn new(path: impl Into<String>, message: impl Into<String>) -> Self {
        Self {
            path: path.into(),
            message: message.into(),
        }
    }
}

impl std::fmt::Display for SchemaError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.path, self.message)
    }
}

impl std::error::Error for SchemaError {}

impl NodeSchema {
    /// Pure instance check: unknown properties, missing `required`, wrong
    /// types, over-length strings, values outside an `enum`, over-size arrays.
    pub fn validate_instance(&self, instance: &Value) -> Result<(), SchemaError> {
        let Some(object) = instance.as_object() else {
            return Err(SchemaError::new("$", "expected an object"));
        };
        for (name, value) in object {
            let Some(property) = self.properties.iter().find(|p| p.name == name.as_str()) else {
                return Err(SchemaError::new(format!("$.{name}"), "unknown property"));
            };
            property.schema.validate(value, &format!("$.{name}"))?;
        }
        for name in &self.required {
            if !object.contains_key(name) {
                return Err(SchemaError::new(
                    format!("$.{name}"),
                    "missing required property",
                ));
            }
        }
        Ok(())
    }
}

impl NodePropertySchema {
    fn validate(&self, value: &Value, path: &str) -> Result<(), SchemaError> {
        match self {
            Self::Scalar(scalar) => scalar.validate(value, path),
            Self::Array {
                items, max_items, ..
            } => {
                let Some(array) = value.as_array() else {
                    return Err(SchemaError::new(path, "expected an array"));
                };
                if array.len() as u32 > *max_items {
                    return Err(SchemaError::new(
                        path,
                        format!("array length {} exceeds maxItems {max_items}", array.len()),
                    ));
                }
                for (index, item) in array.iter().enumerate() {
                    items.validate(item, &format!("{path}[{index}]"))?;
                }
                Ok(())
            }
        }
    }
}

impl NodeScalarSchema {
    fn validate(&self, value: &Value, path: &str) -> Result<(), SchemaError> {
        match self.kind {
            NodeScalarType::String => {
                let Some(text) = value.as_str() else {
                    return Err(SchemaError::new(path, "expected a string"));
                };
                if let Some(max) = self.max_length {
                    let length = text.chars().count() as u32;
                    if length > max {
                        return Err(SchemaError::new(
                            path,
                            format!("string length {length} exceeds maxLength {max}"),
                        ));
                    }
                }
                if let Some(values) = &self.enum_values {
                    if !values.iter().any(|allowed| allowed == text) {
                        return Err(SchemaError::new(path, "value outside the declared enum"));
                    }
                }
                Ok(())
            }
            NodeScalarType::Integer => {
                if value.is_i64() || value.is_u64() {
                    Ok(())
                } else {
                    Err(SchemaError::new(path, "expected an integer"))
                }
            }
            NodeScalarType::Number => {
                if value.is_number() {
                    Ok(())
                } else {
                    Err(SchemaError::new(path, "expected a number"))
                }
            }
            NodeScalarType::Boolean => {
                if value.is_boolean() {
                    Ok(())
                } else {
                    Err(SchemaError::new(path, "expected a boolean"))
                }
            }
        }
    }
}

// --- wire shape: strict parse with field-named errors, symmetric serialization ---

impl Serialize for GraphNodesCap {
    fn serialize<S>(&self, s: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        self.to_value().serialize(s)
    }
}

impl<'de> Deserialize<'de> for GraphNodesCap {
    fn deserialize<D>(d: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        let value = Value::deserialize(d)?;
        Self::from_value(&value).map_err(serde::de::Error::custom)
    }
}

impl GraphNodesCap {
    pub fn to_value(&self) -> Value {
        let mut object = Map::new();
        if !self.converters.is_empty() {
            object.insert(
                "converters".into(),
                Value::Array(
                    self.converters
                        .iter()
                        .map(|conversion| {
                            serde_json::json!({
                                "from": conversion.from.as_str(),
                                "to": conversion.to.as_str(),
                            })
                        })
                        .collect(),
                ),
            );
        }
        if !self.event_sources.is_empty() {
            object.insert(
                "eventSources".into(),
                Value::Array(
                    self.event_sources
                        .iter()
                        .map(EventSourceDecl::to_value)
                        .collect(),
                ),
            );
        }
        Value::Object(object)
    }

    pub fn from_value(value: &Value) -> Result<Self, String> {
        let object = value
            .as_object()
            .ok_or_else(|| format!("{ROOT}: expected an object"))?;
        for key in object.keys() {
            if key != "converters" && key != "eventSources" {
                return Err(format!("{ROOT}: unknown field `{key}`"));
            }
        }
        let converters = match object.get("converters") {
            None => Vec::new(),
            Some(declared) => parse_converters(declared)?,
        };
        let event_sources = match object.get("eventSources") {
            None => Vec::new(),
            Some(declared) => parse_event_sources(declared)?,
        };
        if converters.is_empty() && event_sources.is_empty() {
            return Err(format!(
                "{ROOT}: declare at least one converter or event source"
            ));
        }
        Ok(Self {
            converters,
            event_sources,
        })
    }
}

fn parse_converters(value: &Value) -> Result<Vec<Conversion>, String> {
    let path = format!("{ROOT}.converters");
    let list = value
        .as_array()
        .ok_or_else(|| format!("{path}: expected an array"))?;
    if list.len() > MAX_CONVERTERS {
        return Err(format!(
            "{path}: at most {MAX_CONVERTERS} conversions are allowed"
        ));
    }
    let mut declared: Vec<Conversion> = Vec::with_capacity(list.len());
    for (index, entry) in list.iter().enumerate() {
        let entry_path = format!("{path}[{index}]");
        let object = entry
            .as_object()
            .ok_or_else(|| format!("{entry_path}: expected an object"))?;
        for key in object.keys() {
            if key != "from" && key != "to" {
                return Err(format!("{entry_path}: unknown field `{key}`"));
            }
        }
        let from = parse_media_kind(object.get("from"), &format!("{entry_path}.from"))?;
        let to = parse_media_kind(object.get("to"), &format!("{entry_path}.to"))?;
        if from == to {
            return Err(format!(
                "{entry_path}: from and to are both \"{}\"",
                from.as_str()
            ));
        }
        if let Some(previous) = declared.iter().position(|c| c.from == from && c.to == to) {
            return Err(format!(
                "{entry_path}: duplicate conversion {} -> {} (already declared at index {previous})",
                from.as_str(),
                to.as_str()
            ));
        }
        declared.push(Conversion::new(from, to));
    }
    Ok(declared)
}

fn parse_media_kind(value: Option<&Value>, path: &str) -> Result<MediaKind, String> {
    let Some(raw) = value.and_then(Value::as_str) else {
        return Err(format!("{path}: expected a media kind"));
    };
    MediaKind::parse(raw).ok_or_else(|| format!("{path}: unknown media kind \"{raw}\""))
}

fn parse_event_sources(value: &Value) -> Result<Vec<EventSourceDecl>, String> {
    let path = format!("{ROOT}.eventSources");
    let list = value
        .as_array()
        .ok_or_else(|| format!("{path}: expected an array"))?;
    if list.len() > MAX_EVENT_SOURCES {
        return Err(format!(
            "{path}: at most {MAX_EVENT_SOURCES} event sources are allowed"
        ));
    }
    let mut declared: Vec<EventSourceDecl> = Vec::with_capacity(list.len());
    for (index, entry) in list.iter().enumerate() {
        let entry_path = format!("{path}[{index}]");
        let object = entry
            .as_object()
            .ok_or_else(|| format!("{entry_path}: expected an object"))?;
        for key in object.keys() {
            if !matches!(key.as_str(), "kind" | "title" | "params" | "payload") {
                return Err(format!("{entry_path}: unknown field `{key}`"));
            }
        }
        let kind = parse_kind(object.get("kind"), &format!("{entry_path}.kind"))?;
        if declared.iter().any(|source| source.kind == kind) {
            return Err(format!(
                "{entry_path}.kind: \"{kind}\" is already declared by this plugin"
            ));
        }
        let title = parse_title(object.get("title"), &format!("{entry_path}.title"))?;
        let params = match object.get("params") {
            None | Some(Value::Null) => None,
            Some(schema) => Some(parse_node_schema(schema, &format!("{entry_path}.params"))?),
        };
        let payload = match object.get("payload") {
            None | Some(Value::Null) => None,
            Some(schema) => Some(parse_node_schema(schema, &format!("{entry_path}.payload"))?),
        };
        declared.push(EventSourceDecl {
            kind,
            title,
            params,
            payload,
        });
    }
    Ok(declared)
}

/// `kind` is a namespaced machine id: at least two lowercase dot-separated
/// parts (`telegram.message`), at most 64 bytes.
fn parse_kind(value: Option<&Value>, path: &str) -> Result<String, String> {
    let Some(raw) = value.and_then(Value::as_str) else {
        return Err(format!("{path}: expected a namespaced kind string"));
    };
    if raw.len() > 64 {
        return Err(format!("{path}: must be at most 64 bytes"));
    }
    let parts: Vec<&str> = raw.split('.').collect();
    let valid_part = |part: &str| {
        let mut chars = part.chars();
        matches!(chars.next(), Some(c) if c.is_ascii_lowercase())
            && chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
    };
    if parts.len() < 2 || !parts.iter().all(|part| valid_part(part)) {
        return Err(format!(
            "{path}: \"{raw}\" must match ^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*)+$"
        ));
    }
    Ok(raw.to_string())
}

fn parse_title(value: Option<&Value>, path: &str) -> Result<String, String> {
    let Some(raw) = value.and_then(Value::as_str) else {
        return Err(format!("{path}: expected a title string"));
    };
    if raw.is_empty() || raw.len() > 128 {
        return Err(format!("{path}: must be 1-128 bytes"));
    }
    Ok(raw.to_string())
}

fn parse_node_schema(value: &Value, path: &str) -> Result<NodeSchema, String> {
    let object = value
        .as_object()
        .ok_or_else(|| format!("{path}: expected an object schema"))?;
    for key in object.keys() {
        if !matches!(
            key.as_str(),
            "type" | "properties" | "required" | "additionalProperties"
        ) {
            return Err(format!(
                "{path}: unsupported schema field `{key}` (no $ref, combinators or patternProperties)"
            ));
        }
    }
    if object.get("type").and_then(Value::as_str) != Some("object") {
        return Err(format!("{path}.type: expected \"object\""));
    }
    if let Some(additional) = object.get("additionalProperties") {
        if additional.as_bool() != Some(false) {
            return Err(format!(
                "{path}.additionalProperties: only `false` is supported"
            ));
        }
    }
    let mut properties: Vec<NodeProperty> = Vec::new();
    if let Some(declared) = object.get("properties") {
        let map = declared
            .as_object()
            .ok_or_else(|| format!("{path}.properties: expected an object"))?;
        if map.len() > MAX_SCHEMA_PROPERTIES {
            return Err(format!(
                "{path}.properties: at most {MAX_SCHEMA_PROPERTIES} properties are allowed"
            ));
        }
        for (name, schema) in map {
            properties.push(NodeProperty {
                name: name.clone(),
                schema: parse_property_schema(schema, &format!("{path}.properties.{name}"))?,
            });
        }
    }
    let mut required: Vec<String> = Vec::new();
    if let Some(declared) = object.get("required") {
        let list = declared
            .as_array()
            .ok_or_else(|| format!("{path}.required: expected an array"))?;
        for (index, entry) in list.iter().enumerate() {
            let name = entry
                .as_str()
                .ok_or_else(|| format!("{path}.required[{index}]: expected a property name"))?;
            if !properties.iter().any(|p| p.name == name) {
                return Err(format!(
                    "{path}.required[{index}]: \"{name}\" is not a declared property"
                ));
            }
            required.push(name.to_string());
        }
    }
    Ok(NodeSchema {
        properties,
        required,
    })
}

fn parse_property_schema(value: &Value, path: &str) -> Result<NodePropertySchema, String> {
    let object = value
        .as_object()
        .ok_or_else(|| format!("{path}: expected an object schema"))?;
    let kind = object
        .get("type")
        .and_then(Value::as_str)
        .ok_or_else(|| format!("{path}.type: expected a scalar or array type"))?;
    let description = parse_description(object.get("description"), &format!("{path}.description"))?;
    match kind {
        "array" => {
            for key in object.keys() {
                if !matches!(key.as_str(), "type" | "description" | "items" | "maxItems") {
                    return Err(format!("{path}: unsupported schema field `{key}`"));
                }
            }
            let items = object
                .get("items")
                .ok_or_else(|| format!("{path}.items: required for array properties"))?;
            let items = parse_scalar_schema(items, &format!("{path}.items"))?;
            let max_items = object
                .get("maxItems")
                .and_then(Value::as_u64)
                .filter(|n| *n <= MAX_ARRAY_ITEMS as u64)
                .ok_or_else(|| {
                    format!("{path}.maxItems: expected an integer <= {MAX_ARRAY_ITEMS}")
                })? as u32;
            Ok(NodePropertySchema::Array {
                description,
                items: Box::new(items),
                max_items,
            })
        }
        "object" => Err(format!("{path}.type: nested objects are not supported")),
        _ => {
            for key in object.keys() {
                if !matches!(key.as_str(), "type" | "description" | "enum" | "maxLength") {
                    return Err(format!("{path}: unsupported schema field `{key}`"));
                }
            }
            Ok(NodePropertySchema::Scalar(parse_scalar_fields(
                object,
                path,
                description,
            )?))
        }
    }
}

fn parse_scalar_schema(value: &Value, path: &str) -> Result<NodeScalarSchema, String> {
    let object = value
        .as_object()
        .ok_or_else(|| format!("{path}: expected a scalar schema"))?;
    let kind = object
        .get("type")
        .and_then(Value::as_str)
        .ok_or_else(|| format!("{path}.type: expected a scalar type"))?;
    if matches!(kind, "array" | "object") {
        return Err(format!(
            "{path}.type: array items must be scalars (one level of scalar arrays)"
        ));
    }
    for key in object.keys() {
        if !matches!(key.as_str(), "type" | "description" | "enum" | "maxLength") {
            return Err(format!("{path}: unsupported schema field `{key}`"));
        }
    }
    let description = parse_description(object.get("description"), &format!("{path}.description"))?;
    parse_scalar_fields(object, path, description)
}

fn parse_scalar_fields(
    object: &Map<String, Value>,
    path: &str,
    description: Option<String>,
) -> Result<NodeScalarSchema, String> {
    let raw_kind = object
        .get("type")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let kind = match raw_kind {
        "string" => NodeScalarType::String,
        "integer" => NodeScalarType::Integer,
        "number" => NodeScalarType::Number,
        "boolean" => NodeScalarType::Boolean,
        other => {
            return Err(format!(
                "{path}.type: unknown type \"{other}\" (expected string, integer, number, boolean or array)"
            ))
        }
    };
    let enum_values = match object.get("enum") {
        None | Some(Value::Null) => None,
        Some(declared) => {
            if kind != NodeScalarType::String {
                return Err(format!(
                    "{path}.enum: only string properties may declare enum"
                ));
            }
            let list = declared
                .as_array()
                .ok_or_else(|| format!("{path}.enum: expected an array of strings"))?;
            if list.is_empty() {
                return Err(format!("{path}.enum: expected at least one value"));
            }
            let mut values: Vec<String> = Vec::with_capacity(list.len());
            for (index, entry) in list.iter().enumerate() {
                values.push(
                    entry
                        .as_str()
                        .map(str::to_string)
                        .ok_or_else(|| format!("{path}.enum[{index}]: expected a string"))?,
                );
            }
            Some(values)
        }
    };
    let max_length = match object.get("maxLength") {
        None | Some(Value::Null) => None,
        Some(declared) => {
            if kind != NodeScalarType::String {
                return Err(format!(
                    "{path}.maxLength: only string properties may declare maxLength"
                ));
            }
            let length = declared
                .as_u64()
                .filter(|n| *n <= MAX_STRING_LENGTH as u64)
                .ok_or_else(|| {
                    format!("{path}.maxLength: expected an integer <= {MAX_STRING_LENGTH}")
                })? as u32;
            Some(length)
        }
    };
    Ok(NodeScalarSchema {
        description,
        kind,
        enum_values,
        max_length,
    })
}

fn parse_description(value: Option<&Value>, path: &str) -> Result<Option<String>, String> {
    match value {
        None | Some(Value::Null) => Ok(None),
        Some(declared) => Ok(Some(
            declared
                .as_str()
                .map(str::to_string)
                .ok_or_else(|| format!("{path}: expected a string"))?,
        )),
    }
}

impl EventSourceDecl {
    pub fn to_value(&self) -> Value {
        let mut object = Map::new();
        object.insert("kind".into(), Value::String(self.kind.clone()));
        object.insert("title".into(), Value::String(self.title.clone()));
        if let Some(params) = &self.params {
            object.insert("params".into(), params.to_value());
        }
        if let Some(payload) = &self.payload {
            object.insert("payload".into(), payload.to_value());
        }
        Value::Object(object)
    }
}

impl NodeSchema {
    pub fn to_value(&self) -> Value {
        let mut properties = Map::new();
        for property in &self.properties {
            properties.insert(property.name.clone(), property.schema.to_value());
        }
        let mut object = Map::new();
        object.insert("type".into(), Value::String("object".into()));
        object.insert("properties".into(), Value::Object(properties));
        if !self.required.is_empty() {
            object.insert(
                "required".into(),
                Value::Array(
                    self.required
                        .iter()
                        .map(|name| Value::String(name.clone()))
                        .collect(),
                ),
            );
        }
        Value::Object(object)
    }
}

impl NodePropertySchema {
    fn to_value(&self) -> Value {
        match self {
            Self::Scalar(scalar) => scalar.to_value(),
            Self::Array {
                description,
                items,
                max_items,
            } => {
                let mut object = Map::new();
                object.insert("type".into(), Value::String("array".into()));
                if let Some(description) = description {
                    object.insert("description".into(), Value::String(description.clone()));
                }
                object.insert("items".into(), items.to_value());
                object.insert("maxItems".into(), Value::from(*max_items));
                Value::Object(object)
            }
        }
    }
}

impl NodeScalarSchema {
    fn to_value(&self) -> Value {
        let mut object = Map::new();
        object.insert(
            "type".into(),
            Value::String(
                match self.kind {
                    NodeScalarType::String => "string",
                    NodeScalarType::Integer => "integer",
                    NodeScalarType::Number => "number",
                    NodeScalarType::Boolean => "boolean",
                }
                .into(),
            ),
        );
        if let Some(description) = &self.description {
            object.insert("description".into(), Value::String(description.clone()));
        }
        if let Some(values) = &self.enum_values {
            object.insert(
                "enum".into(),
                Value::Array(values.iter().map(|v| Value::String(v.clone())).collect()),
            );
        }
        if let Some(max) = self.max_length {
            object.insert("maxLength".into(), Value::from(max));
        }
        Value::Object(object)
    }
}

