//! Opaque, frame-scoped access to passive files owned by a plugin.
use std::{collections::HashMap, fs::File, io::{Read, Seek, SeekFrom}, path::{Path, PathBuf}, sync::{Arc, LazyLock, Weak}, time::{Duration, Instant}};
use parking_lot::Mutex;
use serde::Serialize;
use crate::view_host::{ViewProvider, ViewRegistry, ViewRegistryHandle};

mod format;
pub use format::{MediaDeliveryDescriptor, MediaFile, MediaType};

pub const MAX_MEDIA_BYTES: u64 = 256 * 1024 * 1024;
const FRAME_TTL: Duration = Duration::from_secs(1800);
const HANDLE_TTL: Duration = Duration::from_secs(600);
const MAX_FRAMES: usize = 128;
const MAX_HANDLES: usize = 16;
static STORE: LazyLock<Mutex<MediaStore>> = LazyLock::new(|| Mutex::new(MediaStore::default()));

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum MediaRefusal { Unknown, Expired, Foreign }

pub struct ResolvedMedia { pub path: PathBuf, pub file_name: String, pub content_type: String }
pub struct OpenedMedia { pub file: File, pub path: PathBuf, pub file_name: String, pub content_type: String }

#[derive(Serialize)]
pub struct MediaHandle { pub handle: String, pub url: Option<String>, pub content_type: String, pub file_name: String, pub expires_in_seconds: u64 }

struct Frame { plugin: String, provider: Weak<dyn ViewProvider>, registry: Weak<ViewRegistry>, expires: Instant, handles: HashMap<String, Entry> }
struct Entry { root: PathBuf, relative: String, resolved: ResolvedMedia, file: Arc<Mutex<File>>, size: u64, kind: MediaType, expires: Instant }
#[derive(Default)]
struct MediaStore { frames: HashMap<String, Frame> }

pub fn valid_token(value: &str) -> bool { value.len() == 64 && value.bytes().all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b)) }
pub fn valid_plugin_id(value: &str) -> bool { !value.is_empty() && value.len() <= 128 && value.bytes().all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-' || b == b'_') }
fn token() -> String { format!("{}{}", uuid::Uuid::new_v4().simple(), uuid::Uuid::new_v4().simple()) }

impl MediaStore {
    fn cleanup(&mut self, now: Instant) {
        self.frames.retain(|_, frame| {
            frame.handles.retain(|_, entry| entry.expires > now);
            frame.expires > now && frame.provider.strong_count() > 0
        });
    }
    fn frame(&self, plugin: &str, frame: &str, now: Instant) -> Result<&Frame, MediaRefusal> {
        let value = self.frames.get(frame).ok_or(MediaRefusal::Unknown)?;
        if value.plugin != plugin { return Err(MediaRefusal::Foreign); }
        let provider = value.provider.upgrade().ok_or(MediaRefusal::Expired)?;
        let current = value.registry.upgrade().and_then(|registry| registry.get(plugin)).ok_or(MediaRefusal::Expired)?;
        if value.expires <= now || !Arc::ptr_eq(&provider, &current) { return Err(MediaRefusal::Expired); }
        Ok(value)
    }
    fn entry(&self, plugin: &str, frame: &str, handle: &str, now: Instant) -> Result<&Entry, MediaRefusal> {
        let value = self.frame(plugin, frame, now)?.handles.get(handle).ok_or(MediaRefusal::Unknown)?;
        if value.expires <= now { return Err(MediaRefusal::Expired); }
        Ok(value)
    }
}

/// Called only by the authenticated host document loader.
pub fn create_frame(provider: &Arc<dyn ViewProvider>, registry: &ViewRegistryHandle) -> Result<String, MediaRefusal> {
    if !registry.get(provider.id()).is_some_and(|current| Arc::ptr_eq(&current, provider)) { return Err(MediaRefusal::Unknown); }
    let descriptor = provider.media_delivery().ok_or(MediaRefusal::Unknown)?;
    if !valid_plugin_id(provider.id()) || !descriptor.valid() { return Err(MediaRefusal::Unknown); }
    let mut store = STORE.lock();
    store.cleanup(Instant::now());
    if store.frames.len() >= MAX_FRAMES || store.frames.values().filter(|f| f.plugin == provider.id()).count() >= 16 { return Err(MediaRefusal::Unknown); }
    let frame = token();
    store.frames.insert(frame.clone(), Frame { plugin: provider.id().into(), provider: Arc::downgrade(provider), registry: Arc::downgrade(registry), expires: Instant::now() + FRAME_TTL, handles: HashMap::new() });
    Ok(frame)
}

pub fn revoke_frame(plugin: &str, frame: &str) {
    let mut store = STORE.lock();
    if store.frames.get(frame).is_some_and(|value| value.plugin == plugin) { store.frames.remove(frame); }
}
pub fn revoke_plugin(plugin: &str) { STORE.lock().frames.retain(|_, frame| frame.plugin != plugin); }

pub fn frame_provider(plugin: &str, frame: &str) -> Result<Arc<dyn ViewProvider>, MediaRefusal> {
    let mut store = STORE.lock();
    store.cleanup(Instant::now());
    store.frame(plugin, frame, Instant::now())?.provider.upgrade().ok_or(MediaRefusal::Expired)
}

/// Backend output is resolved against the host-chosen plugin data directory only.
pub fn register_media(plugin: &str, frame: &str, source: MediaFile) -> Result<MediaHandle, MediaRefusal> {
    register_at_root(&mut STORE.lock(), plugin, frame, &codeterm_paths::data_dir().join(plugin), source, Instant::now())
}
fn register_at_root(store: &mut MediaStore, plugin: &str, frame: &str, root: &Path, source: MediaFile, now: Instant) -> Result<MediaHandle, MediaRefusal> {
    let owner = store.frame(plugin, frame, now)?;
    let provider = owner.provider.upgrade().ok_or(MediaRefusal::Expired)?;
    let descriptor = provider.media_delivery().ok_or(MediaRefusal::Unknown)?;
    if !descriptor.valid() || !descriptor.types.contains(&source.content_type) || owner.handles.len() >= MAX_HANDLES { return Err(MediaRefusal::Unknown); }
    let opened = open_owned_at_root(root, &source, &descriptor)?;
    let size = opened.file.metadata().map_err(|_| MediaRefusal::Unknown)?.len();
    let file_name = opened.file_name;
    let content_type = opened.content_type;
    let file = opened.file;
    let path = opened.path;
    let handle = token();
    let expires = (now + HANDLE_TTL).min(owner.expires);
    let url = source.content_type.playback().then(|| format!("/api/plugins/{plugin}/media/{frame}/{handle}"));
    store.frames.get_mut(frame).ok_or(MediaRefusal::Expired)?.handles.insert(handle.clone(), Entry { root: root.to_path_buf(), relative: source.path, resolved: ResolvedMedia { path, file_name: file_name.clone(), content_type: content_type.clone() }, file: Arc::new(Mutex::new(file)), size, kind: source.content_type, expires });
    Ok(MediaHandle { handle, url, content_type, file_name, expires_in_seconds: expires.saturating_duration_since(now).as_secs() })
}
fn confined_path(root: &Path, relative: &str) -> Result<PathBuf, MediaRefusal> {
    let expected = root.parent().ok_or(MediaRefusal::Unknown)?.canonicalize().map_err(|_| MediaRefusal::Unknown)?.join(root.file_name().ok_or(MediaRefusal::Unknown)?);
    let root = root.canonicalize().map_err(|_| MediaRefusal::Unknown)?;
    if root != expected { return Err(MediaRefusal::Unknown); }
    let path = root.join(relative).canonicalize().map_err(|_| MediaRefusal::Unknown)?;
    if !path.starts_with(&root) { return Err(MediaRefusal::Unknown); }
    Ok(path)
}

/// Shared validation seam for a host-stamped producer plugin, without frame/run authority.
pub fn open_owned_media(plugin: &str, source: &MediaFile, descriptor: &MediaDeliveryDescriptor) -> Result<OpenedMedia, MediaRefusal> {
    if !valid_plugin_id(plugin) { return Err(MediaRefusal::Unknown); }
    open_owned_at_root(&codeterm_paths::data_dir().join(plugin), source, descriptor)
}
fn open_owned_at_root(root: &Path, source: &MediaFile, descriptor: &MediaDeliveryDescriptor) -> Result<OpenedMedia, MediaRefusal> {
    if !descriptor.valid() || !descriptor.types.contains(&source.content_type) || source.path.len() > 4096 || source.path.contains(['\\', ':', '\0']) { return Err(MediaRefusal::Unknown); }
    let mut file = codeterm_blueprint_types::code_source::open_file(root, &source.path).map_err(|_| MediaRefusal::Unknown)?;
    let size = file.metadata().map_err(|_| MediaRefusal::Unknown)?.len();
    if size == 0 || size > MAX_MEDIA_BYTES { return Err(MediaRefusal::Unknown); }
    let mut head = [0; 32];
    let count = file.read(&mut head).map_err(|_| MediaRefusal::Unknown)?;
    if !source.content_type.matches(&head[..count]) { return Err(MediaRefusal::Unknown); }
    file.seek(SeekFrom::Start(0)).map_err(|_| MediaRefusal::Unknown)?;
    Ok(OpenedMedia { file, path: confined_path(root, &source.path)?, file_name: format::safe_name(source.file_name.as_deref().unwrap_or("media"), source.content_type), content_type: source.content_type.as_str().into() })
}
fn open_entry(entry: &Entry) -> Result<OpenedMedia, MediaRefusal> {
    open_owned_at_root(&entry.root, &MediaFile { path: entry.relative.clone(), content_type: entry.kind, file_name: Some(entry.resolved.file_name.clone()) }, &MediaDeliveryDescriptor { types: vec![entry.kind] })
}
pub fn frame_owns_handle(plugin: &str, frame: &str, handle: &str) -> Result<(), MediaRefusal> {
    let store = STORE.lock();
    let owner = store.frame(plugin, frame, Instant::now())?;
    if !owner.handles.contains_key(handle) { return Err(MediaRefusal::Foreign); }
    store.entry(plugin, frame, handle, Instant::now()).map(|_| ())
}
/// Atomically check exact-frame ownership and open a freshly confined file for gesture actions.
pub fn open_frame_media(plugin: &str, frame: &str, handle: &str) -> Result<OpenedMedia, MediaRefusal> {
    let store = STORE.lock();
    let owner = store.frame(plugin, frame, Instant::now())?;
    if !owner.handles.contains_key(handle) { return Err(MediaRefusal::Foreign); }
    open_entry(store.entry(plugin, frame, handle, Instant::now())?)
}
/// Non-frame consumers must establish their own host authority before calling this resolver.
pub fn open_plugin_media(plugin: &str, handle: &str) -> Result<OpenedMedia, MediaRefusal> {
    let store = STORE.lock();
    for (frame_id, frame) in &store.frames {
        if frame.handles.contains_key(handle) { return open_entry(store.entry(plugin, frame_id, handle, Instant::now())?); }
    }
    Err(MediaRefusal::Unknown)
}
pub fn resolve_plugin_media(plugin: &str, handle: &str) -> Result<ResolvedMedia, MediaRefusal> {
    let opened = open_plugin_media(plugin, handle)?;
    Ok(ResolvedMedia { path: opened.path, file_name: opened.file_name, content_type: opened.content_type })
}

#[derive(Clone)]
pub struct Playback { plugin: String, frame: String, handle: String, pub size: u64, pub content_type: String, file: Arc<Mutex<File>> }
pub fn playback(plugin: &str, frame: &str, handle: &str) -> Result<Playback, MediaRefusal> {
    let store = STORE.lock();
    let entry = store.entry(plugin, frame, handle, Instant::now())?;
    if !entry.resolved.content_type.starts_with("audio/") && !entry.resolved.content_type.starts_with("video/") { return Err(MediaRefusal::Unknown); }
    Ok(Playback { plugin: plugin.into(), frame: frame.into(), handle: handle.into(), size: entry.size, content_type: entry.resolved.content_type.clone(), file: entry.file.clone() })
}
impl Playback {
    /// The caller offloads each bounded read; clones share one explicitly positioned cursor.
    pub fn read(&self, offset: u64, length: usize) -> std::io::Result<Vec<u8>> {
        STORE.lock().entry(&self.plugin, &self.frame, &self.handle, Instant::now()).map_err(|_| std::io::Error::from(std::io::ErrorKind::PermissionDenied))?;
        if length > 65536 || offset > self.size { return Err(std::io::ErrorKind::InvalidInput.into()); }
        let mut file = self.file.lock();
        file.seek(SeekFrom::Start(offset))?;
        let mut bytes = vec![0; length.min(self.size.saturating_sub(offset) as usize)];
        file.read_exact(&mut bytes)?;
        Ok(bytes)
    }
}

#[cfg(test)]
mod tests;

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct MediaDeliveryDescriptor { pub types: Vec<MediaType> }
impl MediaDeliveryDescriptor {
    pub fn valid(&self) -> bool { !self.types.is_empty() && self.types.len() <= 10 && self.types.iter().enumerate().all(|(i, t)| !self.types[..i].contains(t)) }
}
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct MediaFile { pub path: String, pub content_type: MediaType, pub file_name: Option<String> }

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum MediaType {
    #[serde(rename="video/mp4")] Mp4,
    #[serde(rename="video/webm")] Webm,
    #[serde(rename="video/ogg")] OggVideo,
    #[serde(rename="audio/mpeg")] Mp3,
    #[serde(rename="audio/ogg")] OggAudio,
    #[serde(rename="audio/wav")] Wav,
    #[serde(rename="image/png")] Png,
    #[serde(rename="image/jpeg")] Jpeg,
    #[serde(rename="image/webp")] Webp,
    #[serde(rename="image/gif")] Gif,
}
impl MediaType {
    pub fn as_str(self) -> &'static str { match self { Self::Mp4=>"video/mp4", Self::Webm=>"video/webm", Self::OggVideo=>"video/ogg", Self::Mp3=>"audio/mpeg", Self::OggAudio=>"audio/ogg", Self::Wav=>"audio/wav", Self::Png=>"image/png", Self::Jpeg=>"image/jpeg", Self::Webp=>"image/webp", Self::Gif=>"image/gif" } }
    pub fn playback(self) -> bool { self.as_str().starts_with("audio/") || self.as_str().starts_with("video/") }
    fn extension(self) -> &'static str { match self { Self::Mp4=>"mp4", Self::Webm=>"webm", Self::OggVideo|Self::OggAudio=>"ogg", Self::Mp3=>"mp3", Self::Wav=>"wav", Self::Png=>"png", Self::Jpeg=>"jpg", Self::Webp=>"webp", Self::Gif=>"gif" } }
    pub fn matches(self, head: &[u8]) -> bool { match self {
        Self::Mp4 => head.get(4..8) == Some(b"ftyp"),
        Self::Webm => head.starts_with(&[0x1a,0x45,0xdf,0xa3]),
        Self::OggVideo|Self::OggAudio => head.starts_with(b"OggS"),
        Self::Mp3 => head.starts_with(b"ID3") || (head.len()>=2 && head[0]==0xff && head[1]&0xe0==0xe0),
        Self::Wav => head.starts_with(b"RIFF") && head.get(8..12)==Some(b"WAVE"),
        Self::Png => head.starts_with(b"\x89PNG\r\n\x1a\n"),
        Self::Jpeg => head.starts_with(&[0xff,0xd8,0xff]),
        Self::Webp => head.starts_with(b"RIFF") && head.get(8..12)==Some(b"WEBP"),
        Self::Gif => head.starts_with(b"GIF87a") || head.starts_with(b"GIF89a"),
    } }
}
pub(super) fn safe_name(name: &str, kind: MediaType) -> String {
    let stem = name.rsplit_once('.').map_or(name, |(stem,_)| stem);
    let cleaned: String = stem.chars().take(100).map(|c| if c.is_control() || "<>:\"/\\|?*".contains(c) { '_' } else { c }).collect();
    let cleaned = cleaned.trim_matches([' ', '.']);
    let prefix = cleaned.split('.').next().unwrap_or("").trim_end_matches(' ').to_ascii_uppercase();
    let device_suffix = prefix.strip_prefix("COM").or_else(|| prefix.strip_prefix("LPT"));
    let reserved = matches!(prefix.as_str(), "CON"|"PRN"|"AUX"|"NUL") || device_suffix.is_some_and(|suffix| {
        let mut chars = suffix.chars();
        matches!(chars.next(), Some('1'..='9'|'¹'|'²'|'³')) && chars.next().is_none()
    });
    format!("{}.{}", if cleaned.is_empty() || reserved { "media" } else { cleaned }, kind.extension())
}

//! `view` capability — a plugin ships an HTML/JS/CSS UI rendered in a sandboxed,
//! CSP-locked iframe that reaches the host only through the `ct.invoke` bridge.
//! Security boundary: the bridge routes to the single `viewCall` export plus
//! narrowly capability-gated host-owned settings, never arbitrary exports.

use std::sync::Arc;

use async_trait::async_trait;
use serde_json::Value;

use crate::capability::CapabilityRegistry;
use crate::js_runtime::{ViewHostAction, WebhookReceiverKind};

#[derive(Debug)]
pub enum ViewError {
    Call(String),
}

impl std::fmt::Display for ViewError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Call(e) => write!(f, "view call failed: {e}"),
        }
    }
}

impl std::error::Error for ViewError {}

/// A plugin iframe backend. Host-owned ports remain separate from viewCall.
#[async_trait]
pub trait ViewProvider: Send + Sync {
    fn id(&self) -> &str;

    /// The webhook capability served by this view, when it has one.
    fn webhook_receiver_kind(&self) -> Option<WebhookReceiverKind> {
        None
    }

    /// The user-gesture host actions the plugin declared for its view; nothing else is performed.
    fn host_actions(&self) -> &[ViewHostAction] {
        &[]
    }

    fn media_delivery(&self) -> Option<crate::media_delivery::MediaDeliveryDescriptor> { None }

    async fn media_file(&self, _id: &str) -> Result<crate::media_delivery::MediaFile, ViewError> {
        Err(ViewError::Call("media delivery not supported".into()))
    }

    /// Dispatch one `ct.invoke(method, args)` from the iframe to the plugin's
    /// `viewCall(method, args)` export. Returns its JSON result.
    async fn call(&self, method: &str, args: Value) -> Result<Value, ViewError>;
}

pub type ViewRegistry = CapabilityRegistry<dyn ViewProvider>;
pub type ViewRegistryHandle = Arc<ViewRegistry>;

/// Resolve a plugin's on-disk directory by id, scanning the same roots the
/// snapshot uses. The iframe asset route serves `<dir>/ui/*` from here.
pub fn plugin_ui_dir(plugin_id: &str) -> Option<std::path::PathBuf> {
    let workspace = workspace_root();
    for root in crate::js_runtime::default_roots(Some(workspace.as_path())) {
        let dir = root.join(plugin_id);
        if dir.join("ui").join("index.html").exists() {
            return Some(dir.join("ui"));
        }
    }
    None
}

// This crate sits at src-tauri/crates/codeterm-plugin; the repository root owns `plugins/`.
fn workspace_root() -> std::path::PathBuf {
    #[cfg(test)]
    let root = crate::test_support::fixture_manifest_dir().join("../../..");
    #[cfg(not(test))]
    let root = std::path::PathBuf::from(concat!(env!("CARGO_MANIFEST_DIR"), "/../../.."));
    root
}

