//! Seam between plugin view host actions and plugin-owned media files.
//!
//! Host actions only ever see a file media delivery has already opened under
//! the plugin's own data directory for the exact frame generation that owns the
//! handle, so they never reopen a path a symlink could have swapped.

pub use codeterm_plugin::media_delivery::{MediaRefusal, OpenedMedia};

pub trait PluginMediaResolver: Send + Sync {
    /// Open the file behind a host-issued handle for the plugin the host (never the frame) names,
    /// only when that exact frame generation owns the handle; a handle of another frame is `Foreign`.
    /// `frame` is the host-held token of the iframe that asked, never a value the frame supplies.
    fn open(&self, plugin_id: &str, frame: &str, handle: &str) -> Result<OpenedMedia, MediaRefusal>;
}

/// The production resolver: media delivery's atomic frame-ownership check and confined open.
pub struct FrameMedia;

impl PluginMediaResolver for FrameMedia {
    fn open(&self, plugin_id: &str, frame: &str, handle: &str) -> Result<OpenedMedia, MediaRefusal> {
        codeterm_plugin::media_delivery::open_frame_media(plugin_id, frame, handle)
    }
}

/// The handle and frame-token shape the host issues: 64 lowercase hex characters. Anything else is refused unread.
pub fn valid_media_handle(handle: &str) -> bool {
    codeterm_plugin::media_delivery::valid_token(handle)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn media_handles_are_exactly_64_lowercase_hex() {
        assert!(valid_media_handle(&"a1".repeat(32)));
        assert!(!valid_media_handle(&"A1".repeat(32)));
        assert!(!valid_media_handle(&"a1".repeat(31)));
        assert!(!valid_media_handle(&format!("{}/", "a".repeat(63))));
        assert!(!valid_media_handle("../../etc/passwd"));
        assert!(!valid_media_handle(""));
    }

    #[test]
    fn frame_media_refuses_a_frame_the_store_never_issued() {
        let handle = "a".repeat(64);
        assert!(FrameMedia.open("studio", &"b".repeat(64), &handle).is_err());
    }
}

#[cfg(unix)]
use std::ffi::CString;
use std::fs::File;
use std::io::Read;
#[cfg(unix)]
use std::os::fd::{AsRawFd, FromRawFd};
use std::path::{Component, Path};

pub fn read(directory: &Path, relative: &str) -> Result<String, &'static str> {
    read_bounded(directory, relative, 16384)
}

pub fn read_bounded(directory: &Path, relative: &str, max: usize) -> Result<String, &'static str> {
    let root = directory.canonicalize().map_err(|_| "contract_violation")?;
    let file = open_file(&root, relative)?;
    let mut text = String::new();
    file.take(max as u64 + 1)
        .read_to_string(&mut text)
        .map_err(|_| "contract_violation")?;
    if text.len() > max {
        return Err("budget_exhausted");
    }
    Ok(text)
}

/// Open a regular file without following the root or any child symlink/reparse point.
#[cfg(unix)]
pub fn open_file(directory: &Path, relative: &str) -> Result<File, &'static str> {
    let parts = Path::new(relative)
        .components()
        .map(|component| match component {
            Component::Normal(name) => {
                CString::new(name.as_encoded_bytes()).map_err(|_| "contract_violation")
            }
            _ => Err("contract_violation"),
        })
        .collect::<Result<Vec<_>, _>>()?;
    if parts.is_empty() {
        return Err("contract_violation");
    }
    let root = CString::new(directory.as_os_str().as_encoded_bytes())
        .map_err(|_| "contract_violation")?;
    let fd = unsafe {
        libc::open(
            root.as_ptr(),
            libc::O_RDONLY | libc::O_DIRECTORY | libc::O_NOFOLLOW | libc::O_CLOEXEC,
        )
    };
    if fd < 0 {
        return Err("contract_violation");
    }
    let mut parent = unsafe { File::from_raw_fd(fd) };
    let mut source = None;
    for (index, part) in parts.iter().enumerate() {
        let last = index + 1 == parts.len();
        let flags = libc::O_RDONLY
            | libc::O_NOFOLLOW
            | libc::O_CLOEXEC
            | libc::O_NONBLOCK
            | if last { 0 } else { libc::O_DIRECTORY };
        let fd = unsafe { libc::openat(parent.as_raw_fd(), part.as_ptr(), flags) };
        if fd < 0 {
            return Err("contract_violation");
        }
        let file = unsafe { File::from_raw_fd(fd) };
        if last {
            source = Some(file);
            break;
        }
        parent = file;
    }
    let file = source.ok_or("contract_violation")?;
    if !file.metadata().is_ok_and(|metadata| metadata.is_file()) {
        return Err("contract_violation");
    }
    Ok(file)
}

#[cfg(windows)]
mod windows;
#[cfg(windows)]
pub use windows::open_file;

#[cfg(test)]
mod tests;

use super::*;
use std::ffi::OsString;
use std::os::windows::ffi::OsStringExt;
use std::os::windows::fs::{MetadataExt, OpenOptionsExt};
use std::os::windows::io::AsRawHandle;
use std::path::PathBuf;
use windows_sys::Win32::Storage::FileSystem::{
    GetFinalPathNameByHandleW, FILE_ATTRIBUTE_REPARSE_POINT, FILE_FLAG_BACKUP_SEMANTICS,
    FILE_FLAG_OPEN_REPARSE_POINT, FILE_NAME_NORMALIZED, FILE_SHARE_READ,
};

pub fn open_file(directory: &Path, relative: &str) -> Result<File, &'static str> {
    let parts = Path::new(relative)
        .components()
        .map(|component| {
            let Component::Normal(name) = component else {
                return Err("contract_violation");
            };
            Ok(name)
        })
        .collect::<Result<Vec<_>, _>>()?;
    if parts.is_empty() {
        return Err("contract_violation");
    }
    let mut path = directory.to_path_buf();
    let root_handle = open(&path)?;
    if !root_handle
        .metadata()
        .is_ok_and(|metadata| metadata.is_dir())
    {
        return Err("contract_violation");
    }
    let root = final_path(&root_handle)?;
    let mut handles = vec![root_handle];
    for (index, part) in parts.iter().enumerate() {
        path.push(part);
        let metadata = std::fs::symlink_metadata(&path).map_err(|_| "contract_violation")?;
        if metadata.file_attributes() & FILE_ATTRIBUTE_REPARSE_POINT != 0 {
            return Err("contract_violation");
        }
        let handle = open(&path)?;
        let metadata = handle.metadata().map_err(|_| "contract_violation")?;
        if !final_path(&handle)?.starts_with(&root)
            || if index + 1 == parts.len() {
                !metadata.is_file()
            } else {
                !metadata.is_dir()
            }
        {
            return Err("contract_violation");
        }
        handles.push(handle);
    }
    handles.pop().ok_or("contract_violation")
}

fn open(path: &Path) -> Result<File, &'static str> {
    let file = std::fs::OpenOptions::new()
        .read(true)
        .share_mode(FILE_SHARE_READ)
        .custom_flags(FILE_FLAG_OPEN_REPARSE_POINT | FILE_FLAG_BACKUP_SEMANTICS)
        .open(path)
        .map_err(|_| "contract_violation")?;
    if file
        .metadata()
        .map_err(|_| "contract_violation")?
        .file_attributes()
        & FILE_ATTRIBUTE_REPARSE_POINT
        != 0
    {
        return Err("contract_violation");
    }
    Ok(file)
}

fn final_path(file: &File) -> Result<PathBuf, &'static str> {
    let handle = file.as_raw_handle() as _;
    let required =
        unsafe { GetFinalPathNameByHandleW(handle, std::ptr::null_mut(), 0, FILE_NAME_NORMALIZED) };
    if required == 0 || required > 32768 {
        return Err("contract_violation");
    }
    let mut name = vec![0; required as usize + 1];
    let written = unsafe {
        GetFinalPathNameByHandleW(
            handle,
            name.as_mut_ptr(),
            name.len() as u32,
            FILE_NAME_NORMALIZED,
        )
    };
    if written == 0 || written as usize >= name.len() {
        return Err("contract_violation");
    }
    Ok(PathBuf::from(OsString::from_wide(
        &name[..written as usize],
    )))
}

//! Outbound message-stage pipeline. One ordered pipeline of stages, each
//! declaring a [`StageMatch`] slot it grabs (voice = compose-time transcriber,
//! text = send-time `chatPreprocessor`) and passing non-matching messages
//! through. Two stages on the same slot would double-process; [`detect_conflicts`]
//! flags the overlap (warn-and-allow).

use std::sync::Arc;

use crate::ports::ChatPreprocessorPort;
use crate::ports::{ChatPreprocessorProvider, PreprocessCtx};

/// The slot a stage grabs in the outbound pipeline. Part of the conflict guard:
/// two stages on the same slot overlap.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum StageMatch {
    /// Compose-time: a voice attachment → editable text (transcriber).
    Voice,
    /// Send-time: final text → augmented text (chatPreprocessor).
    Text,
}

/// A flagged overlap: `slot` is claimed by more than one stage.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StageConflict {
    pub slot: StageMatch,
    pub ids: Vec<String>,
}

/// Inspect every registered `(id, slot)` and flag slots claimed by >1 stage.
/// Called at install/registration; the result is warned (not blocked).
pub fn detect_conflicts<'a, I>(stages: I) -> Vec<StageConflict>
where
    I: IntoIterator<Item = (&'a str, StageMatch)>,
{
    let mut voice: Vec<String> = Vec::new();
    let mut text: Vec<String> = Vec::new();
    for (id, slot) in stages {
        match slot {
            StageMatch::Voice => voice.push(id.to_string()),
            StageMatch::Text => text.push(id.to_string()),
        }
    }
    let mut out = Vec::new();
    if voice.len() > 1 {
        out.push(StageConflict {
            slot: StageMatch::Voice,
            ids: voice,
        });
    }
    if text.len() > 1 {
        out.push(StageConflict {
            slot: StageMatch::Text,
            ids: text,
        });
    }
    out
}

/// Run [`detect_conflicts`] over the live registries and `log::warn!` each overlap (warn-and-allow; never blocks).
pub fn warn_stage_conflicts(
    transcribers: &crate::transcribe::TranscribeRegistry,
    preprocessors: &dyn ChatPreprocessorPort,
) {
    let voice = transcribers.ids();
    let text = preprocessors.active_preprocessors();
    let inventory: Vec<(&str, StageMatch)> = voice
        .iter()
        .map(|id| (id.as_str(), StageMatch::Voice))
        .collect();
    let mut conflicts = detect_conflicts(inventory);
    conflicts.extend(detect_text_conflicts(
        text.iter()
            .map(|stage| (stage.id(), stage.provider_scope())),
    ));
    for c in conflicts {
        log::warn!(
            "[chatpipeline] {:?} slot grabbed by >1 stage ({}); they would run \
             twice — uninstall one",
            c.slot,
            c.ids.join(", ")
        );
    }
}

pub fn detect_text_conflicts<'a, I>(stages: I) -> Vec<StageConflict>
where
    I: IntoIterator<Item = (&'a str, Option<&'a str>)>,
{
    let mut scopes: std::collections::BTreeMap<Option<&str>, Vec<String>> =
        std::collections::BTreeMap::new();
    for (id, scope) in stages {
        scopes.entry(scope).or_default().push(id.to_string());
    }
    scopes
        .into_values()
        .filter(|ids| ids.len() > 1)
        .map(|ids| StageConflict {
            slot: StageMatch::Text,
            ids,
        })
        .collect()
}

pub fn resolve_text_stages(
    stages: &[Arc<dyn ChatPreprocessorProvider>],
    provider: Option<&str>,
) -> Vec<Arc<dyn ChatPreprocessorProvider>> {
    let scoped: Vec<_> = stages
        .iter()
        .filter(|stage| {
            stage
                .provider_scope()
                .is_some_and(|scope| Some(scope) == provider)
        })
        .cloned()
        .collect();
    let selected = if scoped.is_empty() {
        stages
            .iter()
            .filter(|stage| stage.provider_scope().is_none())
            .cloned()
            .collect()
    } else {
        scoped
    };
    if selected.len() == 1 {
        selected
    } else {
        Vec::new()
    }
}

/// Run the send-time text stages in order; each replaces the text or passes through. Identity with no stages.
pub fn run_text_stages(
    stages: &[Arc<dyn ChatPreprocessorProvider>],
    ctx: &PreprocessCtx,
    text: String,
) -> String {
    let mut current = text;
    for stage in stages {
        if let Some(next) = stage.preprocess(ctx, &current) {
            current = next;
        }
    }
    current
}

/// Whether a send at a user-facing seam should run the send-time text stages.
pub fn is_user_turn_send(is_service_push: bool, has_source_tab: bool, is_agent_tab: bool) -> bool {
    is_agent_tab && !is_service_push && !has_source_tab
}

/// Compose-time voice stage: resolve the active transcriber and turn an audio file
/// into editable text. No active transcriber ⇒ [`TranscribeError::NoBackend`].
pub async fn run_voice_stage(
    transcribers: &crate::transcribe::TranscribeRegistry,
    active_id: &str,
    path: &std::path::Path,
    language: &str,
) -> Result<crate::transcribe::Transcript, crate::transcribe::TranscribeError> {
    match resolve_transcriber(transcribers, active_id) {
        Some(engine) => engine.transcribe(path, language).await,
        None => Err(crate::transcribe::TranscribeError::NoBackend),
    }
}

fn resolve_transcriber(
    transcribers: &crate::transcribe::TranscribeRegistry,
    active_id: &str,
) -> Option<std::sync::Arc<dyn crate::transcribe::Transcriber>> {
    if !active_id.is_empty() {
        if let Some(engine) = transcribers.get(active_id) {
            return Some(engine);
        }
    }

    let mut ids = transcribers.ids();
    ids.sort();
    let id = match ids.as_slice() {
        [] => return None,
        [only] => only,
        many => many
            .iter()
            .find(|id| id.as_str() == "transcriber")
            .unwrap_or(&many[0]),
    };
    transcribers.get(id)
}

